def is_contrarian_family(family: Optional[str]) -> bool:
    if not family:
        return False
    fam_upper = family.upper()
    return any(marker in fam_upper for marker in CONTRARIAN_FAMILY_MARKERS)


def _normalize_series(values: pd.Series) -> pd.Series:
    if values is None or len(values) == 0:
        return pd.Series(dtype=float)
    vals = pd.Series(values).replace([np.inf, -np.inf], np.nan).fillna(0.0)
    total = float(vals.sum())
    if total <= 0:
        return pd.Series(np.ones(len(vals)) / max(len(vals), 1), index=vals.index)
    return vals / total


class ContinuousPredictorEvents:
    """
    Event generator for continuous predictor families.
    
    Converts continuous predictor values into discrete events.
    Supports:
    - Point-in-time Thresholding (Z-Score)
    - Symmetric CUSUM Filter (De Prado)
    
    Families supported:
    - MEAN_REVERSION
    - MARKET_FRAGILITY
    - SURPRISE_Z_CONTINUOUS
    - FLOW_PRESSURE_CONTINUOUS
    - MULTI_HORIZON_SLOPE
    """
    
    def __init__(self, family: str, z_threshold: float = 1.5):
        """Initialize the continuous predictor event generator.
        
        Args:
            family: Base family name (e.g., 'MEAN_REVERSION')
            z_threshold: Z-score threshold for event detection (or h for CUSUM)
        """
        self.family = family
        self.z_threshold = z_threshold
        self._generator = None
        self._cache = {}
    
    def _get_rolling_z_score(self, series: pd.Series, window: int = 2000) -> pd.Series:
        """
        Compute rolling Z-score to prevent look-ahead bias.
        Uses Numba optimized functions if available.
        """
        vals = series.values.astype(np.float32)

        if NUMBA_AVAILABLE:
            # Check for NaNs
            if np.isnan(vals).any():
                vals = np.nan_to_num(vals)

            roll_mean = _numba_rolling_mean(vals, window)
            roll_std = _numba_rolling_std(vals, window)

            # Prevent division by zero
            z = (vals - roll_mean) / (roll_std + 1e-9)
            return pd.Series(z, index=series.index)
        else:
            roll = series.rolling(window=window, min_periods=window//10)
            return (series - roll.mean()) / (roll.std() + 1e-9)

    def _symmetric_cusum_filter(self, series: pd.Series, threshold: float) -> pd.DatetimeIndex:
        """
        Symmetric CUSUM Filter (De Prado, AFML Chapter 2).
        Detects shifts in the mean value of a measured quantity.
        """
        t_events = []
        s_pos = 0.0
        s_neg = 0.0

        # Optimized loop
        vals = series.values
        idx = series.index

        for i in range(len(vals)):
            y = vals[i]
            s_pos = max(0.0, s_pos + y)
            s_neg = min(0.0, s_neg + y)

            if s_pos > threshold:
                s_pos = 0
                t_events.append(idx[i])
            elif s_neg < -threshold:
                s_neg = 0
                t_events.append(idx[i])

        return pd.DatetimeIndex(sorted(list(set(t_events))))

    def generate(self, df: pd.DataFrame, tracker: Any = None, **params) -> Union[pd.DatetimeIndex, pd.Series]:
        """Generate events from continuous predictor values.
        
        Args:
            df: OHLCV DataFrame
            tracker: Optional event generation tracker
            **params:
                - side: 'positive', 'negative', or 'both'
                - method: 'threshold' (default) or 'cusum'
                - normalize: bool (default True) - apply rolling Z-score
                - window: int (default 2000) - window for normalization

        Returns:
            pd.Series of weights indexed by event time, or DatetimeIndex
        """
        if not CONTINUOUS_PREDICTOR_AVAILABLE:
            tprint_warning(f"⚠️ ContinuousPredictorGenerator not available for {self.family}")
            return pd.DatetimeIndex([])
        
        # Cache key based on df shape and family
        # Cache key based on df shape, family, AND params (Robustness Fix)
        # Added explicit versioning to invalidate old caches after recent logic updates
        cache_key = f"{self.family}_v2_{hash(str(df.shape))}_{hash(str(params))}"
        
        if cache_key not in self._cache:
            # Generate all predictors
            self._generator = ContinuousPredictorGenerator(verbose=False)
            all_predictors = self._generator.generate_all_predictors(df)
            
            # KEY FIX: Manually wrap Cross-Asset / Market State features if present in DF
            # These are pre-computed strings (ms__, ca__) that were merged earlier
            # They need to be PredictorGeometry objects to enter the race
            special_prefixes = ('ms__', 'ca__', 'meta__')
            cross_asset_cols = [c for c in df.columns if c.startswith(special_prefixes)]
            
            if cross_asset_cols:
                # tprint_info(f"   Note: Found {len(cross_asset_cols)} cross-asset features in DF, wrapping as geometries")
                for col in cross_asset_cols:
                    family = "CROSS_ASSET_SURPRISE" if col.startswith('ca__') else "MARKET_STATE" if col.startswith('ms__') else "META"
                    
                    # Create generic geometry wrapper
                    # Need to import PredictorGeometry if not available (it is imported at top)
                    geom = PredictorGeometry(
                        name=col,  # Use full column name as predictor name
                        family=family,
                        values=df[col].copy(),
                        metadata={"source": "cross_asset_pipeline", "original_col": col}
                    )
                    all_predictors.append(geom)
            
            self._cache[cache_key] = all_predictors
        else:
            all_predictors = self._cache[cache_key]
        
        # Filter predictors matching this family
        family_predictors = [p for p in all_predictors if p.family == self.family]
        
        if not family_predictors:
            tprint_warning(f"⚠️ No predictors found for family: {self.family}")
            return pd.DatetimeIndex([])
        
        # Aggregate events across all predictors of this family
        event_weights = defaultdict(float)
        side = params.get('side', 'both')
        method = params.get('method', 'threshold')
        normalize = params.get('normalize', True)
        window = params.get('window', 2000)
        
        for pred in family_predictors:
            series = pred.values.fillna(0)
            
            # Apply Rolling Normalization (Look-ahead Safe)
            if normalize:
                z_series = self._get_rolling_z_score(series, window)
            else:
                z_series = series
            
            # Event Logic
            current_events = []
            if method == 'cusum':
                # De Prado CUSUM (on Z-scored series)
                current_events = self._symmetric_cusum_filter(z_series, self.z_threshold)
            else: # 'threshold'
                if side in ['positive', 'both']:
                    pos_events = z_series[z_series > self.z_threshold].index
                    current_events.extend(pos_events)

                if side in ['negative', 'both']:
                    neg_events = z_series[z_series < -self.z_threshold].index
                    current_events.extend(neg_events)

            # Capture weights (intensity = abs(z-score))
            if len(current_events) > 0:
                current_events_idx = pd.DatetimeIndex(sorted(list(set(current_events))))
                # Get absolute Z-scores at event times
                intensities = z_series.loc[current_events_idx].abs()

                # If multiple predictors trigger same event, take max intensity
                for ts, val in intensities.items():
                    event_weights[ts] = max(event_weights[ts], val)
        
        if not event_weights:
            events = pd.DatetimeIndex([])
            if tracker is not None:
                tracker.generated_events = 0
            return events

        # Convert to Series
        sorted_timestamps = sorted(event_weights.keys())
        weights = [event_weights[t] for t in sorted_timestamps]
        events_series = pd.Series(weights, index=pd.DatetimeIndex(sorted_timestamps), name='weight')
        
        if tracker is not None:
            tracker.generated_events = len(events_series)
        
        return events_series

@njit
def vectorized_threshold_classification(scores: np.ndarray, threshold: float = 0.5) -> np.ndarray:
    """
    JIT-compiled vectorized threshold-based classification.

    Args:
        scores: Prediction scores
        threshold: Classification threshold

    Returns:
        Binary classification results
    """
    return (scores >= threshold).astype(np.float64)


class ProbabilityCalibratedModel:
    """
    Wraps a base classifier and applies logistic calibration to its probability outputs.
    """

    def __init__(self, base_model, coef: float, intercept: float):
        self.base_model = base_model
        self.coef_ = coef
        self.intercept_ = intercept
        self.classes_ = getattr(base_model, "classes_", np.array([0, 1]))

    def _apply_calibration(self, raw_probs: np.ndarray) -> np.ndarray:
        if raw_probs.ndim == 1:
            pos = raw_probs
        else:
            pos = raw_probs[:, -1]
        calibrated_pos = expit(self.coef_ * pos + self.intercept_)
        neg = 1.0 - calibrated_pos
        return np.column_stack([neg, calibrated_pos])

    def predict_proba(self, X):
        raw = self.base_model.predict_proba(X)
        return self._apply_calibration(raw)

    def predict(self, X):
        return (self.predict_proba(X)[:, -1] >= 0.5).astype(int)

    def __getattr__(self, item):
        # Prevent infinite recursion if base_model not yet set
        if item == 'base_model' or 'base_model' not in self.__dict__:
            # DEBUG: Log when guard triggers
            # tprint_warning(f"   🔄 [ProbabilityCalibratedModel] __getattr__ guard triggered for '{item}'")
            raise AttributeError(f"'{type(self).__name__}' object has no attribute '{item}'")
        return getattr(self.base_model, item)


class PostHocCalibratedModel:
    """Wrap a classifier with post-hoc probability calibration."""

    def __init__(
        self,
        base_model,
        method: str,
        isotonic_model: Optional[IsotonicRegression] = None,
        temperature: Optional[float] = None,
    ):
        self.base_model = base_model
        self.method = method
        self.isotonic_model = isotonic_model
        self.temperature = temperature
        self.classes_ = getattr(base_model, "classes_", np.array([0, 1]))

    def _apply_temperature(self, probs: np.ndarray) -> np.ndarray:
        if probs.ndim == 1:
            pos = probs
        else:
            pos = probs[:, -1]
        neg = 1.0 - pos
        stacked = np.column_stack([neg, pos])
        temp = self.temperature if self.temperature is not None else 1.0
        scaled = stacked ** temp
        scaled = scaled / (scaled.sum(axis=1, keepdims=True) + 1e-15)
        return scaled

    def predict_proba(self, X):
        raw = self.base_model.predict_proba(X)
        if self.method == "isotonic" and self.isotonic_model is not None:
            if raw.ndim == 1:
                pos = raw
            else:
                pos = raw[:, -1]
            calibrated_pos = self.isotonic_model.transform(pos)
            neg = 1.0 - calibrated_pos
            return np.column_stack([neg, calibrated_pos])
        if self.method == "temperature":
            return self._apply_temperature(raw)
        return raw

    def predict(self, X):
        return (self.predict_proba(X)[:, -1] >= 0.5).astype(int)

    def __getattr__(self, item):
        if item == 'base_model' or 'base_model' not in self.__dict__:
            raise AttributeError(f"'{type(self).__name__}' object has no attribute '{item}'")
        return getattr(self.base_model, item)

