def calculate_ece(y_true, y_prob, n_bins=10):
    """Expected Calibration Error."""
    bin_boundaries = np.linspace(0, 1, n_bins + 1)
    bin_lowers = bin_boundaries[:-1]
    bin_uppers = bin_boundaries[1:]

    ece = 0.0
    for bin_lower, bin_upper in zip(bin_lowers, bin_uppers):
        in_bin = (y_prob > bin_lower) & (y_prob <= bin_upper)
        prop_in_bin = in_bin.mean()
        if prop_in_bin > 0:
            accuracy_in_bin = y_true[in_bin].mean()
            avg_confidence_in_bin = y_prob[in_bin].mean()
            ece += np.abs(avg_confidence_in_bin - accuracy_in_bin) * prop_in_bin

    return ece

def calculate_durbin_watson(residuals):
    """Durbin-Watson statistic."""
    if len(residuals) < 2:
        return 0.0
    diff_sq = np.sum(np.diff(residuals) ** 2)
    res_sq = np.sum(residuals ** 2)
    if res_sq == 0:
        return 0.0
    return diff_sq / res_sq

def calculate_feature_attribution_stability(model, X, y):
    """
    Feature Attribution Stability: Information Ratio of feature importance.
    Metric: Mean(Importance) / Std(Importance) / N_Active_Features
    """
    try:
        # For CalibratedClassifierCV, reach into base estimator
        if hasattr(model, 'calibrated_classifiers_'):
            if len(model.calibrated_classifiers_) > 0:
                model = model.calibrated_classifiers_[0].base_estimator

        # For HuberResidualStack, use internal fashion model
        if isinstance(model, HuberResidualStack):
             if model.fashion_model is not None:
                 model = model.fashion_model
             else:
                 return 0.0

        if hasattr(model, 'estimators_'):
            # Collect importance from each tree
            all_importances = np.array([tree.feature_importances_ for tree in model.estimators_])
            mean_imp = np.mean(all_importances, axis=0)
            std_imp = np.std(all_importances, axis=0)

            active_mask = mean_imp > 0
            n_active = np.sum(active_mask)
            if n_active == 0:
                return 0.0

            stability_ratios = np.divide(
                mean_imp[active_mask],
                std_imp[active_mask],
                out=np.zeros(n_active),
                where=std_imp[active_mask]>0
            )

            stability_ir = np.mean(stability_ratios)
            return stability_ir / n_active

        return 0.0
    except Exception:
        return 0.0

def calculate_brier_skill_score(y_true, y_prob):
    """
    BSS = 1 - BS_model / BS_naive
    BS_naive = Brier Score of predicting mean(y_true) always.
    """
    bs_model = brier_score_loss(y_true, y_prob)
    base_rate = np.mean(y_true)
    y_naive = np.full_like(y_prob, base_rate)
    bs_naive = brier_score_loss(y_true, y_naive)

    if bs_naive < 1e-9:
        return 0.0
    return 1.0 - (bs_model / bs_naive)

class LogitOffsetStack(BaseEstimator):
    """
    Logit Offset Boosting Stack with Robust IRM Fallback.
    Supports both Classification (Logistic) and Regression (Linear/Huber).

    1. 'Law': IRM Linear Model (Baseline).
       - Uses Grid Search for IRM penalty (1.0, 0.1, 0.01).
       - Selects based on Minimax (Worst Environment Loss) robustness.
       - Falls back to Robust SGD if signal is weak.
       - Generates OOF logits via internal CV for 'Fashion' training to prevent leakage.

    2. 'Fashion': GBDT on residuals (offset boosting).
       - Uses 'Law' output as base_margin/init_score.

    3. Output:
       - Classification: sigmoid(Law_Logit + Fashion_Logit).
       - Regression: Law_Pred + Fashion_Residual.
    """
    def __init__(self, huber_params=None, fashion_estimator=None, random_state=42, use_logit_offset=True,
                 irm_grid=[1.0, 0.1, 0.01], n_internal_splits=3, task_type='classification'):
        self.huber_params = huber_params if huber_params else {}
        self.fashion_estimator = fashion_estimator
        self.random_state = random_state
        self.use_logit_offset = use_logit_offset
        self.irm_grid = irm_grid
        self.n_internal_splits = n_internal_splits
        self.task_type = task_type # 'classification' or 'regression'
        self.law_model = None
        self.fashion_model = None
        self.law_killed_ = False
        self._is_fitted = False
        self.feature_importances_ = None

        # Determine classes for sklearn compliance
        if self.task_type == 'classification':
            self.classes_ = np.array([0, 1])

    def fit(self, X, y, sample_weight=None, environment_masks=None, eval_set=None, **kwargs):
        feature_names = getattr(X, 'columns', None)
        try:
            X_arr = check_array(X, accept_sparse=True, ensure_all_finite=False)
        except TypeError:
            X_arr = check_array(X, accept_sparse=True, force_all_finite=False)

        y = np.asarray(y)
        if sample_weight is None:
            sample_weight = np.ones(len(y), dtype=np.float32)

        # Baseline Logic
        alpha = self.huber_params.get('alpha', 0.0001)
        max_iter = self.huber_params.get('max_iter', 1000)

        # 1. Prepare Environment Indices
        env_indices = [np.arange(len(y))]
        if environment_masks:
             try:
                 if isinstance(environment_masks[0], (bool, np.bool_)):
                     pass # Single mask?
                 elif len(environment_masks[0]) == len(y):
                      env_indices = [np.where(m)[0] for m in environment_masks]
                 else:
                      env_indices = environment_masks
             except:
                 pass

        # 2. Select Best Law Model (IRM Grid Search)
        best_law = None
        best_score = float('inf')

        is_classification = (self.task_type == 'classification')

        # Try IRM Grid
        for lam in self.irm_grid:
            try:
                if is_classification:
                    candidate = IRMLinearClassifier(
                        loss_type='logloss', alpha=alpha, max_iter=max_iter, irm_lambda=lam
                    )
                else:
                    candidate = IRMLinearRegressor(
                        loss_type='huber', alpha=alpha, max_iter=max_iter, irm_lambda=lam
                    )

                candidate.fit(X_arr, y, env_indices=env_indices, sample_weight=sample_weight)

                # Evaluate Robustness (Minimax: Maximize Worst Env Loss -> minimize Max(Loss))
                env_losses = []

                if is_classification:
                    preds = candidate.predict_proba(X_arr)[:, 1]
                    metric_func = log_loss
                else:
                    preds = candidate.predict(X_arr)
                    metric_func = mean_squared_error

                for env_idx in env_indices:
                    if len(env_idx) > 0:
                        loss = metric_func(y[env_idx], preds[env_idx], sample_weight=sample_weight[env_idx])
                        env_losses.append(loss)

                # Global loss
                global_loss = metric_func(y, preds, sample_weight=sample_weight)

                worst_case_loss = max(env_losses) if env_losses else global_loss

                if worst_case_loss < best_score:
                    best_score = worst_case_loss
                    best_law = candidate
            except Exception as e:
                continue

        # 3. Fallback to Robust SGD if IRM failed or killed signal
        use_fallback = False
        if best_law is None:
             use_fallback = True
        elif np.max(np.abs(best_law.coef_)) < 1e-9:
             use_fallback = True

        if use_fallback:
             if is_classification:
                 fallback = SGDClassifier(
                     loss='log_loss', alpha=alpha, max_iter=max_iter,
                     penalty='elasticnet', l1_ratio=0.5, random_state=self.random_state
                 )
             else:
                 fallback = SGDRegressor(
                     loss='huber', alpha=alpha, max_iter=max_iter,
                     penalty='elasticnet', l1_ratio=0.5, random_state=self.random_state
                 )

             fallback.fit(X_arr, y, sample_weight=sample_weight)
             best_law = fallback

             # Recalculate best_score
             if is_classification:
                 d = fallback.decision_function(X_arr)
                 probs = expit(d)
                 metric_func = log_loss
                 preds = probs
             else:
                 preds = fallback.predict(X_arr)
                 metric_func = mean_squared_error

             # Evaluate worst case
             env_losses = []
             for env_idx in env_indices:
                 if len(env_idx) > 0:
                     loss = metric_func(y[env_idx], preds[env_idx], sample_weight=sample_weight[env_idx])
                     env_losses.append(loss)
             best_score = max(env_losses) if env_losses else metric_func(y, preds, sample_weight=sample_weight)

        # 4. Survival Gate
        if is_classification:
            dummy_prob = np.average(y, weights=sample_weight)
            dummy_preds = np.full(len(y), dummy_prob)
            metric_func = log_loss
        else:
            dummy_mean = np.average(y, weights=sample_weight)
            dummy_preds = np.full(len(y), dummy_mean)
            metric_func = mean_squared_error

        dummy_env_losses = []
        for env_idx in env_indices:
             if len(env_idx) > 0:
                 loss = metric_func(y[env_idx], dummy_preds[env_idx], sample_weight=sample_weight[env_idx])
                 dummy_env_losses.append(loss)
        dummy_worst_loss = max(dummy_env_losses) if dummy_env_losses else metric_func(y, dummy_preds, sample_weight=sample_weight)

        # Gate: Law must be better (lower loss) than Dummy by margin
        margin = 1e-4
        if best_score > (dummy_worst_loss - margin):
             tprint_warning(f"   ⚠️ Law model failed robust survival gate ({best_score:.4f} vs {dummy_worst_loss:.4f}). Killing.")
             self.law_killed_ = True
             self.law_model = None
             law_logits_train = np.zeros(len(y))
        else:
             self.law_killed_ = False

             # 5. Internal OOF Generation (Prevent Leakage)
             if self.n_internal_splits > 1:
                 oof_preds = np.zeros(len(y))
                 kf = KFold(n_splits=self.n_internal_splits, shuffle=False)

                 base_law = clone(best_law)

                 valid_oof = True
                 for train_idx, val_idx in kf.split(X_arr, y):
                     try:
                         # Prepare Envs for this fold
                         fold_envs = []
                         for env_idx in env_indices:
                             fold_envs.append(np.intersect1d(env_idx, train_idx))

                         # Fit on fold
                         fold_model = clone(base_law)

                         # Fit logic (generic)
                         if isinstance(fold_model, (IRMLinearClassifier, IRMLinearRegressor)):
                             valid_envs = [e for e in fold_envs if len(e) > 10]
                             if not valid_envs: valid_envs = [train_idx]
                             fold_model.fit(X_arr, y, env_indices=valid_envs, sample_weight=sample_weight)
                         else:
                             # SGD
                             w_fold = sample_weight[train_idx] if sample_weight is not None else None
                             fold_model.fit(X_arr[train_idx], y[train_idx], sample_weight=w_fold)

                         # Predict OOF
                         if is_classification:
                             if hasattr(fold_model, "decision_function"):
                                 oof_preds[val_idx] = fold_model.decision_function(X_arr[val_idx])
                             else:
                                 oof_preds[val_idx] = 0.0
                         else:
                             oof_preds[val_idx] = fold_model.predict(X_arr[val_idx])

                     except Exception:
                         valid_oof = False
                         break

                 if valid_oof:
                     law_logits_train = oof_preds
                 else:
                     if is_classification:
                         law_logits_train = best_law.decision_function(X_arr)
                     else:
                         law_logits_train = best_law.predict(X_arr)
             else:
                 # No CV, use in-sample
                 if is_classification:
                     law_logits_train = best_law.decision_function(X_arr)
                 else:
                     law_logits_train = best_law.predict(X_arr)

             self.law_model = best_law

        # 2. Train Fashion Model (Residuals)
        self.fashion_model = clone(self.fashion_estimator)

        # Determine strategy based on model type
        model_type = type(self.fashion_model).__name__
        is_gbdt = 'LGBM' in model_type or 'XGB' in model_type or 'CatBoost' in model_type

        # Determine Mode
        if is_gbdt and self.use_logit_offset:
            self._mode = 'offset'
        else:
            self._mode = 'stacking'

        # Prepare Eval Set (Handle Offset/Stacking)
        fit_kwargs = kwargs.copy()
        if eval_set:
            new_eval_set = []
            eval_init_scores = []

            for X_val, y_val in eval_set:
                try:
                    X_val_arr = check_array(X_val, accept_sparse=True, force_all_finite=False)
                except:
                    X_val_arr = np.array(X_val)

                # Get Law Output for Validation
                val_output = np.zeros(len(y_val))
                if self.law_model and not self.law_killed_:
                    if is_classification:
                        val_output = self.law_model.decision_function(X_val_arr)
                    else:
                        val_output = self.law_model.predict(X_val_arr)

                if self._mode == 'offset':
                    new_eval_set.append((X_val, y_val))
                    eval_init_scores.append(val_output)
                else:
                    X_val_stacked = np.column_stack([X_val_arr, val_output])
                    new_eval_set.append((X_val_stacked, y_val))

            fit_kwargs['eval_set'] = new_eval_set

            # Pass eval_init_score for LGBM
            if self._mode == 'offset' and 'LGBM' in model_type:
                fit_kwargs['eval_init_score'] = eval_init_scores

        if self._mode == 'offset':
            # GBDT: Use Offset Boosting (init_score)
            if hasattr(self.fashion_model, 'set_params') and feature_names is not None:
                params = self.fashion_model.get_params()
                updates = {}
                # Interaction constraints
                ic = params.get('interaction_constraints')
                if ic:
                    valid_features = set(feature_names)
                    new_ic = []
                    for group in ic:
                        valid_group = [f for f in group if f in valid_features]
                        if len(valid_group) >= 2:
                            new_ic.append(valid_group)
                    updates['interaction_constraints'] = new_ic if new_ic else None
                # Monotone constraints
                mc = params.get('monotone_constraints')
                if mc:
                    if isinstance(mc, dict):
                        valid_mc = {k: v for k, v in mc.items() if k in feature_names}
                        updates['monotone_constraints'] = valid_mc if valid_mc else None
                    elif isinstance(mc, (list, tuple)):
                        if len(mc) != len(feature_names):
                            updates['monotone_constraints'] = None
                if updates:
                    self.fashion_model.set_params(**updates)

            # Fit with init_score
            if 'LGBM' in model_type:
                fit_kwargs['init_score'] = law_logits_train
            elif 'XGB' in model_type:
                fit_kwargs['base_margin'] = law_logits_train
            elif 'CatBoost' in model_type:
                fit_kwargs['baseline'] = law_logits_train

            if feature_names is not None:
                X_train_fashion = pd.DataFrame(X_arr, columns=feature_names)
            else:
                X_train_fashion = X_arr

            self.fashion_model.fit(X_train_fashion, y, sample_weight=sample_weight, **fit_kwargs)

        else:
            # RF/ET or unknown: Use Stacking
            X_stacked = np.column_stack([X_arr, law_logits_train])
            self.fashion_model.fit(X_stacked, y, sample_weight=sample_weight, **fit_kwargs)

        self._is_fitted = True
        if hasattr(self.fashion_model, 'feature_importances_'):
             self.feature_importances_ = self.fashion_model.feature_importances_
        return self

    def decision_function(self, X):
        """Returns margins (logits) for classification."""
        if self.task_type != 'classification':
            raise AttributeError("decision_function is only available for classification")

        check_is_fitted(self, '_is_fitted')
        try:
            X_arr = check_array(X, accept_sparse=True, ensure_all_finite=False)
        except TypeError:
            X_arr = check_array(X, accept_sparse=True, force_all_finite=False)

        # Get Law Logits
        law_output = np.zeros(X_arr.shape[0])
        if self.law_model is not None:
            law_output = self.law_model.decision_function(X_arr)

        # Get Fashion Logits
        if self._mode == 'offset':
            if 'LGBM' in type(self.fashion_model).__name__:
                fashion_output = self.fashion_model.predict(X_arr, raw_score=True)
            elif 'XGB' in type(self.fashion_model).__name__:
                fashion_output = self.fashion_model.predict(X_arr, output_margin=True)
            elif 'CatBoost' in type(self.fashion_model).__name__:
                fashion_output = self.fashion_model.predict(X_arr, prediction_type='RawFormulaVal')
            else:
                probs = self.fashion_model.predict_proba(X_arr)[:, 1]
                epsilon = 1e-15
                probs = np.clip(probs, epsilon, 1-epsilon)
                fashion_output = np.log(probs / (1 - probs)) - law_output

            return law_output + fashion_output
        else:
            X_stacked = np.column_stack([X_arr, law_output])
            if hasattr(self.fashion_model, 'decision_function'):
                return self.fashion_model.decision_function(X_stacked)
            else:
                probs = self.fashion_model.predict_proba(X_stacked)[:, 1]
                epsilon = 1e-15
                probs = np.clip(probs, epsilon, 1-epsilon)
                return np.log(probs / (1 - probs))

    def predict_proba(self, X):
        if self.task_type != 'classification':
            raise AttributeError("predict_proba is only available for classification")
        logits = self.decision_function(X)
        probs = expit(logits)
        return np.column_stack([1 - probs, probs])

    def predict(self, X):
        if self.task_type == 'classification':
            return (self.predict_proba(X)[:, 1] >= 0.5).astype(int)
        else:
            # Regression Prediction
            check_is_fitted(self, '_is_fitted')
            try:
                X_arr = check_array(X, accept_sparse=True, ensure_all_finite=False)
            except TypeError:
                X_arr = check_array(X, accept_sparse=True, force_all_finite=False)

            law_output = np.zeros(X_arr.shape[0])
            if self.law_model is not None:
                law_output = self.law_model.predict(X_arr)

            if self._mode == 'offset':
                # For regression, predict usually returns the raw value
                # But check if model expects base_margin logic
                # Most GBDT regression predict() returns sum(base + trees) if base provided at training?
                # Usually no, predict(X) is standalone unless margin provided

                # Since we don't pass base_margin to predict() here (API limit), we assume we need to sum manually
                # UNLESS the model stored the base margin logic? No.

                # Wait, for XGBoost, if we trained with base_margin, predict() might expect it?
                # Or predict() returns just the tree sum?
                # XGBoost: predict(X) returns tree sum if base_margin not provided.
                # LightGBM: predict(X) returns tree sum + global bias?
                # Let's assume we sum manually for safety and consistency.

                if 'LGBM' in type(self.fashion_model).__name__:
                    fashion_output = self.fashion_model.predict(X_arr, raw_score=True) # Raw score is usually the margin
                elif 'XGB' in type(self.fashion_model).__name__:
                    fashion_output = self.fashion_model.predict(X_arr, output_margin=True)
                elif 'CatBoost' in type(self.fashion_model).__name__:
                    fashion_output = self.fashion_model.predict(X_arr, prediction_type='RawFormulaVal')
                else:
                    fashion_output = self.fashion_model.predict(X_arr)
                    # If stacking logic was used in offset mode (fallback), we might have issues.
                    # But generic models shouldn't be in offset mode.

                return law_output + fashion_output
            else:
                X_stacked = np.column_stack([X_arr, law_output])
                return self.fashion_model.predict(X_stacked)

class IRM_ExtraTreesClassifier(ExtraTreesClassifier):
    """ExtraTrees Classifier with IRM compatibility API (Standard training)."""

    def __init__(self, **kwargs):
        self._irm_system = kwargs.pop('irm_system', None)
        self._environment_masks = kwargs.pop('environment_masks', {})
        # Enforce n_jobs=1 to prevent high CPU usage
        kwargs['n_jobs'] = 1
        super().__init__(**kwargs)

    @property
    def irm_system(self):
        return self._irm_system

    @property
    def environment_masks(self):
        return self._environment_masks

    def get_params(self, deep=True):
        params = super().get_params(deep=deep)
        # Ensure private IRM attributes do not leak into sklearn param grid
        params.pop('_irm_system', None)
        params.pop('_environment_masks', None)
        return params

    def set_params(self, **params):
        # Allow explicit updates through sklearn API without leaking into LightGBM
        if 'irm_system' in params:
            self._irm_system = params.pop('irm_system')
        if 'environment_masks' in params:
            self._environment_masks = params.pop('environment_masks')
        return super().set_params(**params)

    def fit(self, X, y, sample_weight=None, **kwargs):
        """Fit standard ExtraTrees (IRM gradient penalty not supported for Forests)."""
        # IRM for Forests is non-trivial (non-differentiable). 
        # We accept the parameters to satisfy the API but run standard training.
        return super().fit(X, y, sample_weight=sample_weight, **kwargs)

if CATBOOST_AVAILABLE_LOCAL:
    class IRM_CatBoostClassifier(CatBoostClassifier):
        """CatBoost Classifier with IRM compatibility API (Standard training)."""

        def __init__(self, thread_count=1, **kwargs):
            self._irm_system = kwargs.pop('irm_system', None)
            self._environment_masks = kwargs.pop('environment_masks', {})
            # Fnforce thread_count=1
            super().__init__(thread_count=1, **kwargs)

        @property
        def irm_system(self):
            return self._irm_system

        @property
        def environment_masks(self):
            return self._environment_masks

        def fit(self, X, y, sample_weight=None, **kwargs):
            """Fit standard CatBoost (Supports custom objective but using standard for stability)."""
            if self.irm_system and not self.environment_masks:
                raise ValueError("IRM enabled but no environment masks provided")
            # Could implement custom objective here, but standard focal loss 
            # (or logloss) is robust enough. Main goal is diversity.
            
            # Sanitize feature names for CatBoost (replace whitespace with underscores)
            mapping = {}
            if hasattr(X, 'columns'):
                X = X.copy()
                new_cols = []
                for c in X.columns:
                    sanitized = str(c).replace(" ", "_").replace(":", "_").replace("[", "(").replace("]", ")").replace("{", "(").replace("}", ")")
                    new_cols.append(sanitized)
                    mapping[c] = sanitized
                X.columns = new_cols
                # Store sanitized column names for predict
                self._sanitized_columns = list(X.columns)
                # tprint_info(f"   🔍 [IRM_CatBoost] Sanitized {len(new_cols)} columns for fit()")

            # --- Fix for Constraint Mismatch (CatBoost) ---
            # CatBoost expects feature names in constraints to MATCH dataset names EXACTLY.
            if hasattr(self, 'get_param'):
                 constraints = self.get_param('monotone_constraints')
                 if constraints and isinstance(constraints, dict) and hasattr(X, 'columns'):
                     # Map original constraint keys to sanitized keys AND filter by presence
                     valid_constraints = {}
                     for k, v in constraints.items():
                         if k in X.columns:
                             valid_constraints[k] = v
                         elif k in mapping and mapping[k] in X.columns:
                             valid_constraints[mapping[k]] = v
                     
                     if len(valid_constraints) != len(constraints):
                          tprint_warning(f"   ⚠️ [IRM_CatBoost] filtered constraints: {len(constraints)} -> {len(valid_constraints)}")
                          # Update the param with valid keys
                          self.set_params(monotone_constraints=valid_constraints)
            # ----------------------------------------------
                
            return super().fit(X, y, sample_weight=sample_weight, **kwargs)


class IRM_LGBMClassifier(lgb.LGBMClassifier):
    """LightGBM Classifier with Invariant Risk Minimization."""

    def __init__(self, random_state=42, n_jobs=1, **kwargs):
        # Store as private to hide from sklearn get_params()
        self._irm_system = kwargs.pop('irm_system', None)
        self._environment_masks = kwargs.pop('environment_masks', {})
        # Ensure random_state is passed explicitly, limit n_jobs
        super().__init__(random_state=random_state, n_jobs=1, **kwargs)

    @property
    def irm_system(self):
        return self._irm_system

    @property
    def environment_masks(self):
        return self._environment_masks

    def fit(self, X, y, sample_weight=None, **kwargs):
        """Fit with IRM objective and robust error handling."""
        # Remove random_state if erroneously passed to fit
        if 'random_state' in kwargs:
            kwargs.pop('random_state')
        
        # NOTE: The IRM training path with custom objective is currently broken.
        # The create_enhanced_irm_trainer expects a PyTorch model, not LightGBM.
        # Setting self.objective = self._irm_focal_objective causes internal issues.
        # For now, always use standard LightGBM training which provides diversity
        # in the model race without the unstable IRM integration.
        # TODO: Implement proper LightGBM+IRM integration if needed.
        # tprint_info(f"   ↪ [IRM_LGBM] Using standard training (IRM integration pending)")
        
        try:
            # Ensure the model is properly fitted
            result = super().fit(X, y, sample_weight=sample_weight, **kwargs)
            # Verify the model was fitted by checking for fitted attributes
            if hasattr(self, 'feature_importances_') or hasattr(self, 'coef_'):
                # tprint_info(f"   ✅ [IRM_LGBM] Successfully fitted")
                return result
            else:
                tprint_warning(f"   ⚠️ [IRM_LGBM] Fit completed but model may not be properly fitted")
                return self
        except Exception as e:
            import traceback
            tprint_warning(f"   ⚠️ [IRM_LGBM] fit failed: {e}")
            tprint_warning(f"   📋 Traceback: {traceback.format_exc()[:500]}")
            
            # Try fallback with minimal parameters
            try:
                tprint_info(f"   🔄 [IRM_LGBM] Attempting fallback fit...")
                tprint_info(f"   🐛 [DEBUG] LGBM Fallback Params: verbose=-1")
                fallback_params = {
                    'verbose': -1
                }
                # Don't reset random_state using set_params as it's already set in init
                self.set_params(**fallback_params)
                result = super().fit(X, y, sample_weight=sample_weight)
                tprint_info(f"   ✅ [IRM_LGBM] Fallback fit successful")
                return result
            except Exception as fallback_e:
                tprint_error(f"   ❌ [IRM_LGBM] Fallback fit also failed: {fallback_e}")
                tprint_error(f"   ❌ [IRM_LGBM] Fallback fit also failed: {fallback_e}")
                # Important: Don't return self (untrained model). 
                # Raise the error so the pipeline knows this model failed.
                raise fallback_e

    def _irm_focal_objective(self, preds, train_data):
        """IRM-aware focal loss objective."""
        # Handle differences between LGBM sklearn API and native API
        if hasattr(preds, 'get_label'):
            # Native API: (preds=train_data, train_data=preds_array)? No, (preds, train_data)
            # But sometimes args are flipped or names are misleading
            labels = preds.get_label()
            preds_val = train_data
        elif hasattr(train_data, 'get_label'):
            # Native API: (preds, train_data)
            labels = train_data.get_label()
            preds_val = preds
        else:
            # Sklearn API wrapper: (y_true, y_pred) usually
            labels = preds
            preds_val = train_data

        # Compute focal loss
        focal_loss = RobustFocalLoss(
            gamma_pos=self._irm_system.focal_gamma if self._irm_system else 1.0,
            gamma_neg=self._irm_system.focal_gamma if self._irm_system else 2.5,
            alpha=self._irm_system.focal_alpha if self._irm_system else 1.0,
            verbose=False
        )

        # Convert to gradient/hessian for LightGBM
        # RobustFocalLoss uses __call__
        grad, hess = focal_loss(preds_val, labels)

        # Add IRM penalty (simplified)
        if self._irm_system and self._environment_masks:
            irm_penalty = self._compute_irm_penalty(preds, labels)
            grad += self._irm_system.lambda_irm * irm_penalty

        return grad, hess

    def _compute_irm_penalty(self, preds, labels):
        """Compute simplified IRM penalty."""
        # Simplified IRM penalty - would need full implementation
        return np.zeros_like(preds)

class IRM_XGBClassifier(XGBClassifier):
    """XGBoost Classifier with Invariant Risk Minimization."""

    def __init__(self, irm_system=None, environment_masks=None, n_jobs=1, **kwargs):
        self._irm_system = irm_system
        self._environment_masks = environment_masks or {}
        # Enforce n_jobs=1
        super().__init__(n_jobs=1, **kwargs)

    @property
    def irm_system(self):
        return self._irm_system

    @property
    def environment_masks(self):
        return self._environment_masks

    def fit(self, X, y, sample_weight=None, **kwargs):
        """Fit with IRM objective."""
        # tprint_info(f"   🐛 [DEBUG] IRM_XGBClassifier.fit called. X shape: {X.shape}")
        
        # --- Enhanced Fix for Constraint Mismatch ---
        # Feature names check
        if hasattr(X, 'columns'):
            feature_names = set(X.columns)
            
            # 1. Monotone Constraints
            if hasattr(self, 'monotone_constraints') and self.monotone_constraints:
                 if isinstance(self.monotone_constraints, dict):
                     # Filter keys to match X.columns
                     valid_constraints = {col: val for col, val in self.monotone_constraints.items() 
                                          if col in feature_names}
                     
                     if len(valid_constraints) != len(self.monotone_constraints):
                         # tprint_warning(f"   ⚠️ [IRM_XGB] Filtered monotone_constraints: {len(self.monotone_constraints)} -> {len(valid_constraints)}")
                         pass
                     self.set_params(monotone_constraints=valid_constraints)
                 elif isinstance(self.monotone_constraints, (list, tuple)):
                     # Reset if length mismatch
                     if len(self.monotone_constraints) != X.shape[1]:
                          tprint_warning(f"   ⚠️ [IRM_XGB] Disabling monotone constraints due to shape mismatch")
                          self.set_params(monotone_constraints=None)
            
        # 2. Interaction Constraints (indices must be valid)
        # 2. Interaction Constraints (indices or names must be valid)
        if hasattr(self, 'interaction_constraints') and self.interaction_constraints:
            valid_interactions = []
            max_feature_idx = X.shape[1] - 1
            feature_names = set(X.columns) if hasattr(X, 'columns') else set()

            for group in self.interaction_constraints:
                # Handle list of lists (groups of features)
                valid_group = []
                for item in group:
                    if isinstance(item, str):
                        # Feature name case
                        if item in feature_names:
                            valid_group.append(item)
                    elif isinstance(item, int):
                        # Feature index case
                        if 0 <= item <= max_feature_idx:
                            valid_group.append(item)
                
                # Only keep groups with at least 2 features remaining
                if len(valid_group) >= 2:
                    valid_interactions.append(valid_group)

            if valid_interactions:
                self.set_params(interaction_constraints=valid_interactions)
            else:
                # tprint_warning("   ⚠️ [IRM_XGB] Disabling interaction_constraints (no valid groups)")
                self.set_params(interaction_constraints=None)
        # -----------------------------------

        # NOTE: XGBoost+IRM integration is enabled.
        if self._irm_system is not None and self._environment_masks:
            tprint_info("   🧠 [IRM_XGB] IRM objective enabled")
            pass

        # Validate input type for feature name access
        has_feature_names = hasattr(X, 'columns')

        # 1. Adapt Monotonic Constraints
        if hasattr(self, 'monotone_constraints') and self.monotone_constraints:
            constraints = self.monotone_constraints

            if isinstance(constraints, dict) and has_feature_names:
                # Map dict {col: val} to tuple matching X columns
                new_constraints = []
                for col in X.columns:
                    new_constraints.append(constraints.get(col, 0))
                self.monotone_constraints = tuple(new_constraints)
                # tprint_info(f"   🔧 Adapted monotonic constraints for {len(X.columns)} features")

            elif isinstance(constraints, (list, tuple)):
                # If tuple length mismatches, we disable constraints to prevent crash
                if has_feature_names and len(constraints) != X.shape[1]:
                    tprint_warning(f"   ⚠️ Mismatch in monotone_constraints ({len(constraints)}) vs features ({X.shape[1]}). Disabling.")
                    self.monotone_constraints = None
                elif not has_feature_names:
                    # If X is numpy, we can't check easily, but XGB might crash if length mismatch
                    # Safe to pass through if lengths match
                    pass

        # 2. Adapt Interaction Constraints
        if hasattr(self, 'interaction_constraints') and self.interaction_constraints:
             if has_feature_names:
                 valid_features = set(X.columns)
                 new_constraints = []
                 if isinstance(self.interaction_constraints, list):
                     for group in self.interaction_constraints:
                         # Filter features in the group that exist in X
                         valid_group = [f for f in group if f in valid_features]
                         if len(valid_group) >= 2:
                             new_constraints.append(valid_group)

                     self.interaction_constraints = new_constraints
             else:
                 # If X is numpy, we cannot validate feature names.
                 # If interaction_constraints use strings, XGB will crash.
                 # We must disable them if we don't have feature names to map.
                 if self.interaction_constraints and isinstance(self.interaction_constraints[0], (list, tuple)) and isinstance(self.interaction_constraints[0][0], str):
                     tprint_warning("   ⚠️ Disabling string-based interaction constraints for numpy input.")
                     self.interaction_constraints = None

        # Standard or IRM training
        try:
            # 3. Auto-Validation Set for Early Stopping
            # XGBoost requires an eval_set if early_stopping_rounds is set.
            # Since the race loop doesn't pass eval_set, we must create one from X, y.
            if hasattr(self, 'early_stopping_rounds') and self.early_stopping_rounds is not None:
                has_eval_set = 'eval_set' in kwargs and kwargs['eval_set'] is not None
                if not has_eval_set:
                    # tprint_info(f"   🐛 [DEBUG] Auto-creating validation set for XGB (Size: {int(len(X)*0.1)})")
                    
                    # Split last 10% for validation
                    split_idx = int(len(X) * 0.9)
                    X_train_sub = X.iloc[:split_idx] if hasattr(X, 'iloc') else X[:split_idx]
                    y_train_sub = y.iloc[:split_idx] if hasattr(y, 'iloc') else y[:split_idx]
                    X_val_sub = X.iloc[split_idx:] if hasattr(X, 'iloc') else X[split_idx:]
                    y_val_sub = y.iloc[split_idx:] if hasattr(y, 'iloc') else y[split_idx:]
                    
                    # Create a copy of kwargs to avoid mutating original dictionary (race safety)
                    fit_kwargs = dict(kwargs)
                    
                    # Update sample weights if present
                    w_train_sub = None
                    if sample_weight is not None:
                        w_train_sub = sample_weight.iloc[:split_idx] if hasattr(sample_weight, 'iloc') else sample_weight[:split_idx]
                        w_val_sub = sample_weight.iloc[split_idx:] if hasattr(sample_weight, 'iloc') else sample_weight[split_idx:]
                        fit_kwargs['eval_sample_weight'] = [w_val_sub]
                    
                    # Update base_margin if present in kwargs to prevent shape mismatch crash
                    if 'base_margin' in fit_kwargs and fit_kwargs['base_margin'] is not None:
                        bm = fit_kwargs['base_margin']
                        bm_train = bm.iloc[:split_idx] if hasattr(bm, 'iloc') else bm[:split_idx]
                        bm_val = bm.iloc[split_idx:] if hasattr(bm, 'iloc') else bm[split_idx:]
                        fit_kwargs['base_margin'] = bm_train
                        fit_kwargs['eval_base_margin'] = [bm_val]

                    # Set eval_set and use sub-datasets for training
                    fit_kwargs['eval_set'] = [(X_val_sub, y_val_sub)]
                    fit_kwargs['verbose'] = False # Reduce noise
                    
                    # Call fit with SUBSETS
                    # Note: We don't pass eval_sample_weight/eval_base_margin to fit() directly 
                    # as XGBClassifier doesn't support them in sklearn-style fit() call.
                    # Instead, XGBoost handles those via the DMatrix internal conversion if they are in the booster params.
                    # For now, we'll strip them to avoid TypeError.
                    fit_kwargs.pop('eval_sample_weight', None)
                    fit_kwargs.pop('eval_base_margin', None)
                    
                    super().fit(X_train_sub, y_train_sub, sample_weight=w_train_sub, **fit_kwargs)
                    return self

            super().fit(X, y, sample_weight=sample_weight, **kwargs)
            return self
        except Exception as e:
            import traceback
            tprint_warning(f"   ⚠️ [IRM_XGB] Standard fit failed: {e}")
            if hasattr(self, 'monotone_constraints'):
                tprint_warning(f"   📋 Monotone constraints type: {type(self.monotone_constraints)}")
            tprint_warning(f"   📋 Traceback: {traceback.format_exc()[:500]}")
            return self

    def _irm_focal_objective(self, preds, dtrain, sample_weight=None, **kwargs):
        """IRM-aware focal loss objective for XGBoost."""
        # Handle both DMatrix and numpy array inputs
        if hasattr(dtrain, 'get_label'):
            labels = dtrain.get_label()
        else:
            # dtrain is a numpy array when passed from sklearn wrapper
            labels = np.asarray(dtrain)
        
        # XGBoost parses sample_weight internally and attaches it to dtrain
        # But if it tries to pass it as an argument, kwargs catches it
        
        # Compute focal loss gradient/hessian
        focal_obj = get_focal_loss_xgb(
            alpha=self._irm_system.focal_alpha if self._irm_system else 1.0,
            gamma=self._irm_system.focal_gamma if self._irm_system else 2.0
        )

        # This would need proper XGBoost objective function integration
        # For now, return standard focal loss
        # Apply sigmoid to convert log-odds to probabilities for RobustFocalLoss
        preds_prob = 1.0 / (1.0 + np.exp(-preds))
        return focal_obj(preds_prob, dtrain)

@njit
def vectorized_weight_assignment(n_samples: int, weight_value: float = 1.0) -> np.ndarray:
    """
    JIT-compiled vectorized weight assignment.

    Args:
        n_samples: Number of samples
        weight_value: Weight value to assign

    Returns:
        Weight array
    """
    return np.full(n_samples, weight_value, dtype=np.float64)


def recall_at_precision_threshold(y_true, y_probs, target_precision: float = 0.60) -> float:
    """
    Calculate Recall at a fixed Precision threshold.
    
    For base models: "What percentage of opportunities can we capture 
    while maintaining X% precision?"
    
    Args:
        y_true: Binary labels (0/1)
        y_probs: Predicted probabilities
        target_precision: Target precision level (e.g., 0.60 = 60% precision)
        
    Returns:
        Recall when maintaining target_precision
    """
    y_true = np.asarray(y_true)
    y_probs = np.asarray(y_probs)
    
    total_positives = y_true.sum()
    
    # Edge cases
    if total_positives == 0:
        return 0.0
    if len(y_true) == 0:
        return 0.0
    
    # Sort by probability descending
    sorted_indices = np.argsort(y_probs)[::-1]
    sorted_labels = y_true[sorted_indices]
    
    # Walk through predictions maintaining precision
    cumsum_tp = np.cumsum(sorted_labels)
    cumsum_fp = np.arange(1, len(sorted_labels) + 1) - cumsum_tp
    
    # Calculate precision at each point
    precision_at_each = cumsum_tp / (cumsum_tp + cumsum_fp + 1e-10)
    
    # Find cutoff where precision drops below target
    valid_indices = np.where(precision_at_each >= target_precision)[0]
    
    if len(valid_indices) == 0:
        return 0.0  # Can't maintain target precision
    
    cutoff_idx = valid_indices[-1] + 1  # Last index maintaining precision
    
    # Calculate recall at this cutoff
    tp_at_cutoff = sorted_labels[:cutoff_idx].sum()
    recall = tp_at_cutoff / total_positives if total_positives > 0 else 0.0
    
    return recall

