class LabelBasedLayer2(BaseStep):
    """
    Layer 2: Regime-Conditional Geometry Optimization & Meta-Labeling.
    """

    _component_singletons: Dict[str, Any] = {}
    _specialist_registration_cache: Dict[str, Tuple[str, int]] = {}
    _model_race_seed_models: Dict[str, Dict[str, Any]] = {}

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._stage_metrics = []
        self._huber_output_cache = {}

    def _precompute_geometry_base_features(self, df: pd.DataFrame):
        tprint_info(f"🚀 [DEBUG] Inside _precompute_geometry_base_features with df shape {df.shape}")
        """
        Pre-compute common rolling features for the entire dataset ONCE using JIT.
        Now supports multi-asset data via asset_id grouping to prevent bleed-over.
        """
        # If already computed for this exact dataframe (by length/index), return
        # Simple heuristic: check length
        if self._geometry_base_features is not None and len(self._geometry_base_features) == len(df):
            return

        tprint_info(f"   ⚡ Pre-computing vectorized base features for {len(df)} bars...")

        def _compute_single_group(group):
            # Calculate Effective Price (VWAP if volume available, else Close)
            if 'volume' in group.columns:
                # Use window=5 consistent with apply_layer2_price_processing
                effective_price = _calculate_rolling_vwap(group['close'], group['volume'], window=5)
            else:
                effective_price = group['close']

            # Prepare data for JIT
            price = effective_price.values.astype(np.float32)
            price_pct = vectorized_pct_change_jit(price)
            price_abs_pct = np.abs(price_pct)

            # Calculate features using JIT
            # Windows: 5, 10, 20, 100
            roll5_sum = rolling_mean_jit(price_pct, 5) * 5
            roll10_sum = rolling_mean_jit(price_pct, 10) * 10
            roll10_sum_abs = rolling_mean_jit(price_abs_pct, 10) * 10
            roll20_mean = rolling_mean_jit(price_pct, 20)
            roll20_std = rolling_std_jit(price_pct, 20)
            roll100_std = rolling_std_jit(price_pct, 100)
            roll5_std = rolling_std_jit(price_pct, 5)

            # Additional expensive rolling max/min for Range families
            # Using effective_price for consistency
            roll20_max = effective_price.rolling(20).max()
            roll20_min = effective_price.rolling(20).min()
            roll5_max = effective_price.rolling(5).max()
            roll5_min = effective_price.rolling(5).min()

            # Precompute rolling volume means (used across multiple families)
            if 'volume' in group.columns:
                roll20_volume_mean = group['volume'].rolling(20).mean()
                roll10_volume_mean = group['volume'].rolling(10).mean()
            else:
                roll20_volume_mean = pd.Series(0.0, index=group.index)
                roll10_volume_mean = pd.Series(0.0, index=group.index)

            res = pd.DataFrame({
                'effective_price': effective_price,
                'roll5_sum': roll5_sum,
                'roll10_sum': roll10_sum,
                'roll10_sum_abs': roll10_sum_abs,
                'roll20_mean': roll20_mean,
                'roll20_std': roll20_std,
                'roll100_std': roll100_std,
                'roll5_std': roll5_std,
                'price_pct': price_pct,
                'price_abs_pct': price_abs_pct,
                'roll20_max': roll20_max,
                'roll20_min': roll20_min,
                'roll5_max': roll5_max,
                'roll5_min': roll5_min,
                'roll20_volume_mean': roll20_volume_mean,
                'roll10_volume_mean': roll10_volume_mean
            }, index=group.index)
            if '_tmp_row_id' in group.columns:
                res['_tmp_row_id'] = group['_tmp_row_id']
            return res

        # Multi-asset handling
        if 'asset_id' in df.columns:
            # Group by asset_id and apply logic
            # Handle duplicate indices by using a temporary row ID
            df = df.copy()
            df['_tmp_row_id'] = np.arange(len(df))
            chunks = []
            
            # Fix ambiguity: if asset_id is in both index and columns, use the column series explicitly
            if 'asset_id' in df.index.names:
                grouper = df['asset_id']
            else:
                grouper = 'asset_id'
                
            # sort=False to preserve order of groups if possible, but we reindex anyway
            for _, group in df.groupby(grouper, sort=False):
                chunks.append(_compute_single_group(group))

            if chunks:
                base_df = pd.concat(chunks)
                # Realign to original index using integer position to handle non-unique indices
                if '_tmp_row_id' in base_df.columns:
                    base_df = base_df.sort_values('_tmp_row_id').drop(columns=['_tmp_row_id'])
                else:
                    # Fallback if somehow missing
                    base_df = base_df.reindex(df.index)
            else:
                base_df = pd.DataFrame(index=df.index)
        else:
            base_df = _compute_single_group(df)

        self._geometry_base_features = base_df

    def __init__(self, step_name: str = 'label_based_layer_2', **kwargs):
        # Initialize BaseStep with step name
        super().__init__(step_name)
        self.symbol = kwargs.get('symbol')
        self.init_config = kwargs
        self._dataset_fingerprint: Optional[str] = None
        self._label_batch_cache: Dict[str, Tuple[Dict[str, pd.Series], Dict[str, pd.Series]]] = {}
        self._confounder_cache: Dict[str, pd.DataFrame] = {}
        self._geometry_base_features = None  # Cache for vectorized geometry base features
        self._huber_output_cache: Dict[Tuple[Any, ...], Dict[str, Any]] = {}

        # Initialize LabelBasedLayer2 specific parameters
        transaction_cost = kwargs.get('transaction_cost', None)
        self.n_trials = kwargs.get('n_trials', 60)
        self.n_splits = kwargs.get('n_splits', 2)
        self.random_state = kwargs.get('random_state', 42)
        self.verbose = kwargs.get('verbose', True)
        self.force_hpo = kwargs.get('force_hpo', False)
        
        # Set transaction cost if not provided
        if transaction_cost is None:
            try:
                from src.utils.ml_common.transaction_costs import DEFAULT_TRANSACTION_COST
                transaction_cost = DEFAULT_TRANSACTION_COST
            except Exception:
                transaction_cost = 0.003  # Default fallback
        
        self.transaction_cost = float(transaction_cost)
        
        # Denoised price configuration
        self.use_denoised_prices = kwargs.get('use_denoised_prices', True)
        self.layer0_params = None
        self._denoised_price_cache: Dict[str, pd.Series] = {}

        # Model comparison configuration
        self.enable_model_race = kwargs.get('enable_model_race', True)
        self.model_race_candidates = kwargs.get(
            'model_race_candidates',
            ['CatBoost', 'XGB_Tree', 'XGB_Residual', 'ExtraTrees', 'ExtraTrees_Stack']
        )
        self.model_race_oof_splits = int(kwargs.get('model_race_oof_splits', 5))
        self.model_race_oof_purge_minutes = int(kwargs.get('model_race_oof_purge_minutes', 0))
        self.model_race_oof_embargo_minutes = int(kwargs.get('model_race_oof_embargo_minutes', 0))
        self.model_race_calibration_ece_threshold = float(
            kwargs.get('model_race_calibration_ece_threshold', 0.02)
        )
        self.model_race_calibration_min_samples = int(
            kwargs.get('model_race_calibration_min_samples', 50)
        )
        # AEDL Framework Parameters
        self.enable_aedl = kwargs.get("enable_aedl", True)
        self.aedl_spectral_vision = kwargs.get("aedl_spectral_vision", True)
        self.aedl_causal_compression = kwargs.get("aedl_causal_compression", True)
        self.aedl_resonance_detection = kwargs.get("aedl_resonance_detection", True)
        
        # Spectral Chaser Parameters
        self.spectral_chaser_enabled = kwargs.get("spectral_chaser_enabled", True)
        self.spectral_chaser_models = kwargs.get("spectral_chaser_models", ['xgb', 'catboost', 'rf', 'linear'])
        self.spectral_chaser_cv_folds = kwargs.get("spectral_chaser_cv_folds", 5)
        
        # RSV Integration Parameters
        self.rsv_integration_enabled = kwargs.get("rsv_integration_enabled", True)
        self.rsv_position_sizing = kwargs.get("rsv_position_sizing", True)
        # RSV Integration Parameters
        self.rsv_integration_enabled = kwargs.get("rsv_integration_enabled", True)
        self.rsv_position_sizing = kwargs.get("rsv_position_sizing", True)
        self.rsv_regime_aware = kwargs.get("rsv_regime_aware", True)
        
        # Causal Surprise Parameters
        self.causal_surprise_enabled = kwargs.get("causal_surprise_enabled", True)
        self.zone3_specialist_boost = kwargs.get("zone3_specialist_boost", 3.0)
        self.zone2_specialist_boost = kwargs.get("zone2_specialist_boost", 2.0)
        self.zone_score_exposure = float(kwargs.get("zone_score_exposure", 1.0))
        zone_score_config = kwargs.get("zone_score_config")
        self.zone_score_config = (
            self._default_zone_score_config() if zone_score_config is None else dict(zone_score_config)
        )
        
        # OOF Analytics Parameter
        self.sr_levels = []

        # RobustFocalLoss HPO configuration
        self.enable_focal_hpo = kwargs.get('enable_focal_hpo', False)
        self.focal_hpo_n_trials = kwargs.get('focal_hpo_n_trials', 20)
        
        # Initialize Checkpoint Manager
        self.checkpoint_manager = get_checkpoint_manager()
        
        # Initialize config
        self._current_config = {}
        self.signal_weights = None
        
        # Initialize caches
        self._events_cache = {}
        self._feature_cache = {}
        self._global_probe_features = {}
        self._probe_data_cache = {}
        self._label_cache = {}
        self._weight_cache = {}
        self.regime_labels = None
        self._signals_cache = {}
        self._global_feature_cache = {}  # Global feature cache for entire dataset
        self._global_event_cache = {}    # Global event cache
        self._model_cache = {}           # Cache trained models
        self._feature_selection_cache = {}  # Cache feature selections
        self._label_computation_cache = {}  # Cache label computations
        self._geometry_label_backups = {}  # Preserve labels for downstream stages
        self._max_cache_entries = int(kwargs.get("layer2_max_cache_entries", 6))
        self._gate_feature_cache = {}
        self._treatment_matrix_cache = {}
        self._treatment_cache_dir = Path(kwargs.get("layer2_treatment_cache_dir", "outcomes/cache"))
        self._treatment_cache_dir.mkdir(parents=True, exist_ok=True)

        # Adaptive gating + probe controls
        self.layer2_gate_min_score = float(kwargs.get("layer2_gate_min_score", 0.03))
        self.layer2_gate_percentile = float(kwargs.get("layer2_gate_percentile", 50.0))
        self.layer2_gate_jaccard_max = float(kwargs.get("layer2_gate_jaccard_max", 0.90))
        self.layer2_gate_min_candidates = int(kwargs.get("layer2_gate_min_candidates", 3))
        self.layer2_gate_max_candidates = int(kwargs.get("layer2_gate_max_candidates", 10))
        self.probe_max_samples = int(kwargs.get("layer2_probe_max_samples", 5000))
        self.probe_min_samples = int(kwargs.get("layer2_probe_min_samples", 1000))

        # Composite score blending (structural vs empirical)
        self.structural_score_weight = float(kwargs.get('structural_score_weight', 0.6))
        self.empirical_score_weight = float(kwargs.get('empirical_score_weight', 0.4))
        weight_sum = self.structural_score_weight + self.empirical_score_weight
        if weight_sum == 0:
            self.structural_score_weight = 0.6
            self.empirical_score_weight = 0.4
            weight_sum = 1.0
        self.structural_score_weight /= weight_sum
        self.empirical_score_weight /= weight_sum

        # Preserve candidate labels until downstream consumers release them
        self.preserve_candidate_labels = kwargs.get('preserve_candidate_labels', True)

    def _default_zone_score_config(self) -> Dict[str, float]:
        """Return tightened zone scoring defaults applied to every specialist."""
        return {
            # Maintain smooth mapping while capping extreme boosts
            "power": 2.0,
            "cap": 0.99,
            # Stricter Zone 3 contract and trimmed lower-zone boosts
            "zone3_floor": 0.92,
            "zone3_ratio_boost": 0.35,
            "zone2_ratio_boost": 0.12,
            # Preserve existing contract weights so legacy specialists remain stable
            "core_min_share_multiplier": 0.5,
            "core_max_dispersion_multiplier": 1.0,
            "conditional_min_share_multiplier": 2.0,
            "conditional_weight_cap": 0.5,
            "conditional_weight_multiplier": 0.7,
            "weak_weight_multiplier": 0.3,
            "use_continuous_mapping": True,
        }

    def _initialize_instance(self, kwargs: Dict[str, Any]) -> None:
        """Initialize all internal state, configuration, and components for Layer 2."""
        # Initialize diagnostics
        self._all_tree_stats = []
        
        # Comprehensive metrics tracking for 12-layer process
        self._stage_metrics = []
        self._geometry_optimization_metrics = {}
        self._model_race_metrics = {}
        self._feature_selection_evolution = []
        self._cv_fold_metrics = []
        self._temporal_performance_metrics = {}
        
        # Metadata tracking for 12-layer process
        self._backbone_structure = {}
        self._geometry_selection_metadata = {}
        self._geometry_performance_metrics = {}
        self._label_batch_metadata = {}
        self._causal_graph = {}
        self._geometry_metadata = {}
        self._race_calibration_records = {}
        
        # Checkpoint manager for sub-step resume capability
        self._checkpoint_manager = Layer2CheckpointManager()

