    def _prune_cache(self, cache: Dict[str, Any], max_entries: int, cache_name: str) -> None:
        """Prune cache to manage memory usage."""
        if max_entries <= 0:
            return
        removed = 0
        while len(cache) > max_entries:
            cache.pop(next(iter(cache)), None)
            removed += 1
        if removed:
            tprint_info(f"   🧹 Pruned {removed} entries from {cache_name} cache (max {max_entries})")
            gc.collect()

    def _handle_error(self, e: Exception, context: str, fatal: bool = False):
        """
        Standardized error handling and logging.

        Args:
            e: The exception caught.
            context: Description of where the error occurred.
            fatal: If True, raises Layer2FatalError. If False, logs and raises Layer2RecoverableError.
        """
        msg = f"Error in {context}: {str(e)}"
        if fatal:
            tprint_error(f"❌ CRITICAL: {msg}")
            raise Layer2FatalError(msg) from e
        else:
            tprint_warning(f"⚠️ RECOVERABLE: {msg}")
            # We can either raise a RecoverableError to be caught by the caller
            # or just log it if the caller handles control flow.
            # Here we raise it so caller knows to skip/retry.
            raise Layer2RecoverableError(msg) from e

    def _get_process_memory(self) -> float:
        """Get current process memory usage in MB."""
        try:
            process = psutil.Process(os.getpid())
            return process.memory_info().rss / (1024 * 1024)
        except Exception:
            return 0.0

    def _log_stage_metrics(self, stage_name: str, input_shape: Tuple = None, output_shape: Tuple = None):
        """Log metrics for a pipeline stage."""
        mem_usage = self._get_process_memory()

        # Create metrics object
        metrics = Layer2StageMetrics(
            stage_name=stage_name,
            timestamp=datetime.now().isoformat(),
            input_data_shape=input_shape if input_shape else (0, 0),
            output_data_shape=output_shape,
            processing_time=0.0, # Placeholder, can be updated if we track duration
            memory_usage_mb=mem_usage
        )

        self._stage_metrics.append(metrics)

        shape_str = f"In={input_shape}" if input_shape else ""
        if output_shape:
            shape_str += f" -> Out={output_shape}"

        tprint_info(f"   📊 [Metrics] {stage_name}: Mem={mem_usage:.1f}MB {shape_str}")

    def _convert_single_asset_frame_to_dollar_bars(
        self,
        df: pd.DataFrame,
        config: Dict[str, Any],
        *,
        log_label: str,
        cache_suffix: Optional[str] = None,
    ) -> Optional[pd.DataFrame]:
        """Convert a single-asset frame to dollar bars using adaptive thresholds."""
        if df is None or df.empty:
            return None

        symbol = config.get('symbol', log_label or 'UNKNOWN')
        cache_suffix = cache_suffix or log_label or symbol
        cache_key = f"{symbol}_{cache_suffix}_{df.index.min()}_{df.index.max()}"

        if cache_key in self._dollar_bar_cache:
            tprint_info(f"   [DollarBars] Using cached dollar bars for {log_label}")
            return self._dollar_bar_cache[cache_key]

        try:
            tprint_info(
                f"📊 Converting to dollar bars for {log_label} (target: {self.dollar_bar_target_per_day} bars/day)..."
            )

            base_timeframe = config.get("timeframe", "15m")
            interval_minutes = 15.0 if base_timeframe == "15m" else 1.0

            tprint_info(
                f"   📊 [{log_label}] Using passed DataFrame for dollar bar generation (interval={interval_minutes}m, shape={df.shape})"
            )

            df_source = df.copy()

            if 'quote_volume' not in df_source.columns or df_source['quote_volume'].count() < 0.5 * len(df_source):
                tprint_info(f"   [DollarBars] '{log_label}' quote_volume missing or sparse, recalculating from vol*close")
                df_source['quote_volume'] = df_source['volume'] * df_source['close']

            df_source['quote_volume'] = df_source['quote_volume'].fillna(0.0)

            src_index = df_source.index
            if isinstance(src_index, pd.MultiIndex):
                ts_level = 'timestamp' if 'timestamp' in src_index.names else src_index.names[0]
                src_timestamps = src_index.get_level_values(ts_level)
            else:
                src_timestamps = src_index
            src_timestamps = pd.to_datetime(src_timestamps)
            total_duration_minutes = (src_timestamps.max() - src_timestamps.min()).total_seconds() / 60
            total_days = total_duration_minutes / 1440.0

            threshold_multiplier = 15.0 / interval_minutes

            if total_days < 35:
                global_median_vol = df_source['quote_volume'].median()
                dynamic_threshold = pd.Series(global_median_vol * threshold_multiplier, index=df_source.index)
                tprint_info(
                    f"   📊 [DollarBars] {log_label} short history ({total_days:.1f} days) → global median threshold {global_median_vol * threshold_multiplier:.2f}"
                )
            else:
                days_window = 30
                minutes_in_window = days_window * 24 * 60
                window_size = int(minutes_in_window / interval_minutes)
                min_periods = int(1440 / interval_minutes)
                rolling_30d_median = df_source['quote_volume'].rolling(window=window_size, min_periods=min_periods).median()
                dynamic_threshold = rolling_30d_median * threshold_multiplier

            global_fallback = df_source['quote_volume'].median() * threshold_multiplier
            dynamic_threshold = dynamic_threshold.fillna(global_fallback)

            times = src_timestamps.values
            opens = np.ascontiguousarray(df_source['open'].values, dtype=np.float32)
            highs = np.ascontiguousarray(df_source['high'].values, dtype=np.float32)
            lows = np.ascontiguousarray(df_source['low'].values, dtype=np.float32)
            closes = np.ascontiguousarray(df_source['close'].values, dtype=np.float32)
            vols = np.ascontiguousarray(df_source['quote_volume'].values, dtype=np.float32)
            threshold_vals = np.ascontiguousarray(dynamic_threshold.values, dtype=np.float32)
            times_arr = np.ascontiguousarray(times)

            (
                db_times_arr,
                db_opens_arr,
                db_highs_arr,
                db_lows_arr,
                db_closes_arr,
                db_vols_arr,
            ) = _numba_generate_dollar_bars(times_arr, opens, highs, lows, closes, vols, threshold_vals)

            if len(df_source) < 3000:
                min_bar_count = max(100, len(df_source) // 3)
            else:
                min_bar_count = max(1000, len(df_source) // 3)
            tprint_info(
                f"   📊 [DollarBars] {log_label} result: {len(db_times_arr)} bars (min required: {min_bar_count})"
            )
            if len(db_times_arr) < min_bar_count:
                tprint_warning(
                    f"   ⚠️ [DollarBars] {log_label} produced {len(db_times_arr)} bars (<{min_bar_count}); using original data"
                )
                fallback_df = df_source.copy()
                if 'bar_duration' not in fallback_df.columns:
                    fallback_df['bar_duration'] = (
                        fallback_df.index.to_series().diff().dt.total_seconds().fillna(60.0)
                    )
                fallback_df.attrs['dollar_bar_fallback'] = True
                return fallback_df

            res_df = pd.DataFrame(
                {
                    'open': db_opens_arr,
                    'high': db_highs_arr,
                    'low': db_lows_arr,
                    'close': db_closes_arr,
                    'volume': db_vols_arr,
                },
                index=pd.DatetimeIndex(db_times_arr),
            )

            res_df['bar_duration'] = res_df.index.to_series().diff().dt.total_seconds().fillna(60.0)
            res_df.attrs['dollar_bar_fallback'] = False

            nan_counts = res_df.isna().sum()
            if nan_counts.sum() > 0:
                tprint_warning(
                    f"   ⚠️ [DollarBars] {log_label} contains NaNs: {nan_counts[nan_counts > 0].to_dict()}"
                )
            else:
                tprint_info(f"   ✅ [DollarBars] {log_label} clean (0 NaNs)")

            self._dollar_bar_cache[cache_key] = res_df

            avg_duration_min = res_df['bar_duration'].mean() / 60.0
            tprint_success(
                f"   ✅ Dollar bars [{log_label}]: {len(df_source)} → {len(res_df)} samples (avg duration {avg_duration_min:.1f}m)"
            )

            return res_df

        except Exception as e:
            tprint_error(f"   ❌ Dollar bar conversion failed for {log_label}: {e}")
            return None

    def _attach_asset_identity(
        self,
        res_df: pd.DataFrame,
        asset_key: Optional[str],
        asset_value: Any,
        *,
        asset_from_index: bool,
        timestamp_name: Optional[str],
    ) -> pd.DataFrame:
        """Ensure the converted dataframe preserves asset identity for downstream steps."""
        if not asset_key or asset_value is None or res_df is None:
            return res_df

        if asset_from_index:
            ts_name = timestamp_name or 'timestamp'
            asset_index = pd.MultiIndex.from_arrays(
                [res_df.index, np.full(len(res_df), asset_value)],
                names=[ts_name, asset_key],
            )
            res_df = res_df.copy()
            res_df.index = asset_index

        if asset_key not in res_df.columns:
            res_df = res_df.copy()
            res_df[asset_key] = asset_value

        return res_df

    def _convert_to_dollar_bars(self, df: pd.DataFrame, config: Dict[str, Any]) -> Optional[pd.DataFrame]:
        """
        Convert OHLCV data to adaptive dollar bars.
        Handles both single-asset and multi-asset inputs by converting
        each asset independently when necessary.
        """
        asset_series, asset_key, asset_from_index = self._get_asset_identity_series(df)
        if asset_series is not None:
            asset_series = asset_series.reindex(df.index)
            unique_assets = [val for val in asset_series.dropna().unique().tolist() if val is not None]
        else:
            unique_assets = []

        timestamp_name = None
        if isinstance(df.index, pd.MultiIndex):
            if 'timestamp' in df.index.names:
                timestamp_name = 'timestamp'
            else:
                timestamp_name = next((name for name in df.index.names if name), 'timestamp')
        else:
            timestamp_name = df.index.name or 'timestamp'

        if unique_assets and len(unique_assets) > 1:
            tprint_info(
                f"   🌍 [DollarBars] Multi-asset input detected ({len(unique_assets)} assets); converting per asset for alignment."
            )
            converted_frames = []
            for asset_value in unique_assets:
                mask = asset_series == asset_value
                asset_df = df.loc[mask].copy()
                if asset_df.empty:
                    continue
                if asset_from_index and isinstance(asset_df.index, pd.MultiIndex):
                    asset_df = asset_df.droplevel(asset_key)
                log_label = str(asset_value)
                asset_config = config.copy()
                asset_config['symbol'] = asset_config.get('symbol', log_label)
                converted = self._convert_single_asset_frame_to_dollar_bars(
                    asset_df,
                    asset_config,
                    log_label=log_label,
                    cache_suffix=log_label,
                )
                if converted is None or converted.empty:
                    continue
                converted = self._attach_asset_identity(
                    converted,
                    asset_key,
                    asset_value,
                    asset_from_index=True,
                    timestamp_name=timestamp_name,
                )
                converted_frames.append(converted)

            if not converted_frames:
                return None

            combined = pd.concat(converted_frames).sort_index()
            return combined

        # Single-asset (or unidentified) pathway
        log_label = str(unique_assets[0]) if unique_assets else config.get('symbol', 'UNKNOWN')
        converted = self._convert_single_asset_frame_to_dollar_bars(
            df,
            config,
            log_label=log_label,
            cache_suffix=log_label,
        )
        if converted is None:
            return None

        if unique_assets:
            converted = self._attach_asset_identity(
                converted,
                asset_key,
                unique_assets[0],
                asset_from_index=asset_from_index,
                timestamp_name=timestamp_name,
            )

        return converted

    def _resolve_cross_asset_key(self, candidate: Any, keys: Iterable[Any]) -> Optional[str]:
        """Resolve the key in cross_asset_data matching the provided asset identifier."""
        if candidate is None:
            return None
        keys = list(keys or [])
        if not keys:
            return None

        candidate_str = str(candidate)
        if not candidate_str:
            return None

        def _variants(value: str) -> List[str]:
            vals = [value, value.upper(), value.lower()]
            if value.upper().endswith("USDT"):
                base = value[:-4]
                vals.extend([base, base.upper(), base.lower()])
            elif value.upper().endswith("USD"):
                base = value[:-3]
                vals.extend([base, base.upper(), base.lower()])
            return list(dict.fromkeys([v for v in vals if v]))

        variants = _variants(candidate_str)
        key_set = set(keys)
        for variant in variants:
            if variant in key_set:
                return variant

        lower_map = {str(k).lower(): k for k in keys}
        for variant in variants:
            lower = variant.lower()
            if lower in lower_map:
                return lower_map[lower]

        for variant in variants:
            for key in keys:
                key_str = str(key)
                if variant in key_str or key_str in variant:
                    return key

        return None

    def _sync_cross_asset_payload_with_bars(self, df: pd.DataFrame, config: Dict[str, Any]) -> None:
        """Update config['cross_asset_data'] entries with the latest dollar-bar aligned frames."""
        payload = config.get("cross_asset_data")
        if not isinstance(payload, dict) or not payload:
            return

        asset_series, asset_key, asset_from_index = self._get_asset_identity_series(df)

        if asset_series is None:
            symbol = config.get('symbol', 'UNKNOWN')
            target_key = self._resolve_cross_asset_key(symbol, payload.keys())
            if target_key:
                payload[target_key] = df
                tprint_info(f"   🔄 Updating cross_asset_data[{target_key}] with dollar bars for alignment")
            else:
                tprint_warning(
                    f"   ⚠️ Could not match primary symbol {symbol} to cross_asset_data keys {list(payload.keys())}"
                )
            return

        asset_series = asset_series.reindex(df.index)
        unique_assets = [val for val in asset_series.dropna().unique().tolist() if val is not None]

        for asset_value in unique_assets:
            mask = asset_series == asset_value
            asset_slice = df.loc[mask].copy()
            if asset_slice.empty:
                continue
            if asset_from_index and isinstance(asset_slice.index, pd.MultiIndex):
                asset_slice = asset_slice.droplevel(asset_key)

            target_key = self._resolve_cross_asset_key(asset_value, payload.keys())
            if not target_key:
                tprint_warning(
                    f"   ⚠️ Unable to find cross_asset_data key for asset '{asset_value}'. Available keys: {list(payload.keys())}"
                )
                continue

            payload[target_key] = asset_slice
            tprint_info(f"   🔄 Updating cross_asset_data[{target_key}] with dollar bars for alignment")

    def _generate_price_based_treatments(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Generate De Prado-aligned Treatment (T) features for DML computation.
        
        Layer 2 does NOT use specialists as treatments - instead we use
        the proper Treatment features from De Prado's 2026 Causal Protocol:
        - Tick-Rule Imbalance (order flow)
        - Volume Force (price-volume interaction)
        - VWAP Z-Score (deviation from fair value)
        - Momentum Persistence (streak patterns)
        - Range Aggression (volatility intensity)
        
        These are "Alpha Drivers" - features that can act as causal treatments
        for returns, distinguishable from confounders (Nuisance W) and 
        effect modifiers (X).
        
        Args:
            df: DataFrame with OHLCV data
            
        Returns:
            DataFrame with De Prado-aligned treatment features
        """
        tprint_info("   🎯 Generating De Prado-aligned treatments (no specialists)...")
        
        treatments = pd.DataFrame(index=df.index)
        close = df['close']
        volume = df['volume']
        high = df['high']
        low = df['low']

        # Calculate Effective Price (VWAP) if volume available
        if 'volume' in df.columns:
            effective_price = _calculate_rolling_vwap(close, volume, window=5)
        else:
            effective_price = close

        delta_c = close.diff()
        delta_p = effective_price.diff() # For volume force
        
        # 1. Tick-Rule Imbalance: sum(V * sign(delta C)) - Order Flow Signal (Keep Close)
        treatments['t_tick_imbalance_10'] = (volume * np.sign(delta_c)).rolling(10).sum().fillna(0)
        treatments['t_tick_imbalance_20'] = (volume * np.sign(delta_c)).rolling(20).sum().fillna(0)
        
        # 2. Volume Force: log(|delta P|) * log(V) - Price-Volume Interaction (Use VWAP delta)
        treatments['t_volume_force'] = (np.log(delta_p.abs() + 1e-9) * np.log(volume + 1e-9)).fillna(0)
        
        # 3. VWAP Z-Score: Deviation from "fair" VWAP price
        vwap = (close * volume).rolling(20).sum() / (volume.rolling(20).sum() + 1e-9)
        treatments['t_vwap_zscore'] = ((close - vwap) / (close.rolling(20).std() + 1e-9)).fillna(0)
        
        # 4. Range Aggression: (H-L)/V intensity - Volatility per unit volume
        treatments['t_range_aggression'] = ((high - low) / (volume + 1e-9)).fillna(0)
        
        # 5. Momentum Persistence: Z-score of price streaks (Vectorized, use VWAP)
        price_values = effective_price.values.astype(np.float32)
        treatments['t_momentum_persistence'] = pd.Series(
            _numba_streak_persistence(price_values, window=20),
            index=df.index
        ).fillna(0)
        
        # 6. Shannon Entropy (Binary path predictability) - 24-bar rolling (Vectorized, use VWAP returns)
        vwap_returns = effective_price.pct_change().fillna(0).values.astype(np.float32)
        treatments['t_shannon_entropy_24'] = pd.Series(
            _numba_rolling_entropy(vwap_returns, window=24, bins=5),
            index=df.index
        ).fillna(0)
        
        # 7. Velocity proxy (first difference of smoothed VWAP)
        smooth_price = effective_price.ewm(span=10).mean()
        treatments['t_velocity'] = smooth_price.diff().fillna(0)
        
        # 8. Acceleration proxy (second difference of smoothed VWAP)
        treatments['t_acceleration'] = treatments['t_velocity'].diff().fillna(0)
        
        # Normalize to prevent scale issues in DML
        for col in treatments.columns:
            series = treatments[col]
            std = series.std()
            if std > 1e-9:
                treatments[col] = (series - series.mean()) / std
        
        treatments = treatments.fillna(0)
        tprint_info(f"   ✅ De Prado treatments: {len(treatments.columns)} features (T-set aligned)")
        
        return treatments

    def _get_bootstrap_cache_key(self, train_events, lookback):
        """Generate cache key for bootstrap weights."""
        events_str = f"{len(train_events)}_{train_events.min()}_{train_events.max()}_{lookback}"
        return f"bootstrap_{hash(events_str)}"

    def _get_cached_bootstrap_weights(self, train_events, X_tr, event_ends=None, lookback=100):
        """
        Get cached sequential bootstrap weights or compute and cache them.
        Major optimization: O(n²) computation → O(1) lookup for repeated candidates.
        """
        cache_key = self._get_bootstrap_cache_key(train_events, lookback)
        
        # Check cache
        if cache_key in self._bootstrap_cache:
            if self.verbose:
                tprint_info(f"   💾 Bootstrap cache hit: {len(train_events)} events")
            return self._bootstrap_cache[cache_key]
        
        # Compute weights (expensive O(n²) operation)
        if self.verbose:
            tprint_info(f"   🔄 Computing bootstrap weights for {len(train_events)} events...")
        
        sample_weights = self._sequential_bootstrap_sample_weights(
            train_events, event_ends=event_ends, X=X_tr, lookback=lookback
        )
        
        # Cache result (with size limit)
        if len(self._bootstrap_cache) >= self._max_cache_size:
            # Remove oldest entry
            oldest_key = next(iter(self._bootstrap_cache))
            del self._bootstrap_cache[oldest_key]
            if self.verbose:
                tprint_info(f"   🗑️ Bootstrap cache: removed oldest entry")
        
        self._bootstrap_cache[cache_key] = sample_weights
        
        if self.verbose:
            tprint_info(f"   💾 Bootstrap cached: {len(train_events)} events")
        
        return sample_weights

    def _get_har_cache_key(self, price_series, regime_id=None):
        """Generate cache key for HAR innovations."""
        # Use price series hash and regime for uniqueness
        price_hash = hash(str(price_series.values.tobytes())[:50])  # Partial hash for efficiency
        return f"har_{price_hash}_{regime_id or 'default'}"

    def _get_cached_har_innovations(self, df, regime_id=None):
        """
        Get cached HAR innovations or compute and cache them.
        Major optimization: repeated regression → O(1) lookup.
        """
        if 'close' not in df.columns:
            return None
        
        price_series = df['close']
        cache_key = self._get_har_cache_key(price_series, regime_id)
        
        # Check cache
        if cache_key in self._har_innovation_cache:
            if self.verbose:
                tprint_info(f"   💾 HAR cache hit: {len(price_series)} price points")
            return self._har_innovation_cache[cache_key]
        
        # Compute HAR innovations (expensive regression operation)
        if self.verbose:
            tprint_info(f"   🔄 Computing HAR innovations for {len(price_series)} price points...")
        
        try:
            # Calculate returns
            ret_series = np.log(price_series).diff()
            
            # Build HAR features
            df_har = pd.DataFrame(index=ret_series.index)
            df_har['y'] = ret_series
            df_har['d'] = ret_series.shift(1)  # Daily lag
            df_har['w'] = ret_series.rolling(5).mean().shift(1)  # Weekly
            df_har['m'] = ret_series.rolling(22).mean().shift(1)  # Monthly
            
            clean = df_har.dropna()
            
            if len(clean) < 100:
                if self.verbose:
                    tprint_warning(f"   ⚠️ Insufficient data for HAR: {len(clean)} < 100")
                return None
            
            # Fit HAR model
            from sklearn.linear_model import LinearRegression
            model_har = LinearRegression().fit(clean[['d', 'w', 'm']], clean['y'])
            
            # Extract innovations
            innovation = clean['y'] - model_har.predict(clean[['d', 'w', 'm']])
            
            # Studentize
            y_causal_series = innovation / (innovation.rolling(20).std() + 1e-9)
            
            # Cache result (with size limit)
            if len(self._har_innovation_cache) >= self._max_cache_size:
                # Remove oldest entry
                oldest_key = next(iter(self._har_innovation_cache))
                del self._har_innovation_cache[oldest_key]
                if self.verbose:
                    tprint_info(f"   🗑️ HAR cache: removed oldest entry")
            
            self._har_innovation_cache[cache_key] = y_causal_series
            
            if self.verbose:
                tprint_info(f"   💾 HAR cached: {len(y_causal_series)} innovations")
            
            return y_causal_series
            
        except Exception as e:
            if self.verbose:
                tprint_warning(f"   ⚠️ HAR computation failed: {e}")
            return None

    def clear_performance_caches(self):
        """Clear performance optimization caches."""
        self._bootstrap_cache.clear()
        self._har_innovation_cache.clear()
        if self.verbose:
            tprint_info("   🗑️ Cleared performance caches")

    def get_cache_stats(self):
        """Get cache statistics for monitoring."""
        return {
            'bootstrap_cache_size': len(self._bootstrap_cache),
            'har_cache_size': len(self._har_innovation_cache),
            'max_cache_size': self._max_cache_size
        }

    def _get_family_feature_cache(self, family: str, X: pd.DataFrame, y: pd.Series) -> Optional[List[str]]:
        """
        Get cached feature set for a family if available. 
        Uses a heuristic: if we have computed features for this family on the same dataset/target, reuse them.
        """
        if not family or not self._family_feature_cache:
            return None
            
        # Simplified key: Family + number of features (rough data proxy)
        key = f"{family}_{X.shape[1]}"
        return self._family_feature_cache.get(key)
    
    def _run_timestamp_integrity_test(self, df: pd.DataFrame, geometry, X: pd.DataFrame, y: pd.Series) -> Dict[str, Any]:
        """
        Run Timestamp Integrity Test to detect hidden leakage.
        Logic: Randomly shift feature timestamps forward by 1 bar (lagging the data).
        If CV performance IMPROVES, it implies the original alignment was flawed (e.g. looking at future?).
        Ideally, lagging features (using older data) should degrade performance.
        """
        try:
            tprint_info(f"   🕵️ Running Timestamp Integrity Test on {geometry.uuid[:8]}...")

            # 1. Baseline Performance
            # Use a fast model (LGBM with minimal params)
            clf = lgb.LGBMClassifier(n_estimators=100, max_depth=3, verbose=-1, random_state=42, n_jobs=1)

            # Simple TimeSeriesSplit
            tscv = TimeSeriesSplit(n_splits=3)

            baseline_scores = []
            lagged_scores = []

            X_lagged = X.shift(1).fillna(0)

            for train_idx, val_idx in tscv.split(X):
                X_tr, y_tr = X.iloc[train_idx], y.iloc[train_idx]
                X_val, y_val = X.iloc[val_idx], y.iloc[val_idx]

                # Check for single class
                if y_tr.nunique() < 2 or y_val.nunique() < 2: continue

                clf.fit(X_tr, y_tr)
                p_base = clf.predict_proba(X_val)[:, 1]
                score_base = roc_auc_score(y_val, p_base)
                baseline_scores.append(score_base)

                # Lagged
                X_tr_lag, X_val_lag = X_lagged.iloc[train_idx], X_lagged.iloc[val_idx]
                clf.fit(X_tr_lag, y_tr)
                p_lag = clf.predict_proba(X_val_lag)[:, 1]
                score_lag = roc_auc_score(y_val, p_lag)
                lagged_scores.append(score_lag)

            avg_base = np.mean(baseline_scores) if baseline_scores else 0.0
            avg_lag = np.mean(lagged_scores) if lagged_scores else 0.0

            diff = avg_lag - avg_base
            status = "PASS"
            if diff > 0.02: # Significant improvement from lagging
                status = "FAIL (Leakage Suspected)"
                tprint_warning(f"   ⚠️ Timestamp Integrity Check FAILED: Lagged ({avg_lag:.4f}) > Baseline ({avg_base:.4f})")
            else:
                tprint_success(f"   ✅ Timestamp Integrity Check PASSED: Lagged ({avg_lag:.4f}) <= Baseline ({avg_base:.4f})")

            return {
                'baseline_auc': avg_base,
                'lagged_auc': avg_lag,
                'diff': diff,
                'status': status
            }

        except Exception as e:
            tprint_warning(f"   ⚠️ Timestamp Integrity Test failed: {e}")
            return {'status': 'ERROR', 'error': str(e)}

        """Compute temporal performance degradation metrics."""
        temporal_metrics = {}
        
        for geo_uuid, preds in oof_predictions.items():
            if len(preds) < 100:  # Skip if too few predictions
                continue
                
            # Split into temporal windows
            windows = self._create_temporal_windows(preds.index, n_windows=4)
            window_performance = []
            
            for window_start, window_end in windows:
                window_preds = preds[(preds.index >= window_start) & (preds.index <= window_end)]
                window_returns = returns[(returns.index >= window_start) & (returns.index <= window_end)]
                
                if len(window_preds) > 10 and len(window_returns) > 10:
                    # Compute performance metrics for this window
                    window_auc = self._compute_window_auc(window_preds, window_returns)
                    window_sharpe = self._compute_window_sharpe(window_preds, window_returns)
                    window_performance.append({
                        "window_start": window_start,
                        "window_end": window_end,
                        "auc": window_auc,
                        "sharpe": window_sharpe,
                        "n_predictions": len(window_preds)
                    })
            
            temporal_metrics[geo_uuid] = {
                "window_performance": window_performance,
                "performance_decay": self._compute_performance_decay(window_performance),
                "stability_score": self._compute_temporal_stability(window_performance)
            }
        
        return temporal_metrics
        
    def _set_family_feature_cache(self, family: str, features: List[str], X_shape: int):
        """Store feature set for a family."""
        if not family or not features:
            return
        key = f"{family}_{X_shape}"
        self._family_feature_cache[key] = features
        self._prune_cache(self._family_feature_cache, self._max_cache_entries, "family feature")

    def _prefilter_correlated_candidates(
        self, 
        candidates: List['GeometryTrial'], 
        df: pd.DataFrame,
        max_correlation: float = 0.90
    ) -> List['GeometryTrial']:
        """
        Pre-filter redundant geometry candidates before survival filtering.
        
        Removes highly correlated candidates within each family to prevent
        CI score penalties from overlapping signals. Keeps the candidate
        with higher initial score.
        
        Args:
            candidates: List of geometry candidates
            df: Market data DataFrame for feature computation
            max_correlation: Maximum allowed correlation between candidates
            
        Returns:
            Filtered list of candidates
        """
        tprint_info(f"   🔍 Prefilter correlated candidates start count={len(candidates)}")
        if len(candidates) < 2:
            tprint_info("   ✅ Prefilter correlated candidates skip (insufficient candidates)")
            return candidates
        
        # Group by family
        family_groups: Dict[str, List['GeometryTrial']] = {}
        for cand in candidates:
            family = getattr(cand, 'family', 'UNKNOWN')
            if family not in family_groups:
                family_groups[family] = []
            family_groups[family].append(cand)
        
        filtered_candidates = []
        total_pruned = 0
        
        for family, family_cands in family_groups.items():
            if len(family_cands) < 2:
                filtered_candidates.extend(family_cands)
                continue
            
            # Sort by initial score (higher is better)
            sorted_cands = sorted(
                family_cands, 
                key=lambda x: getattr(x, 'final_score', 0), 
                reverse=True
            )
            
            # Vectorized Matrix-based Jaccard Filtering
            try:
                # 1. Map all events to a sparse matrix
                # Candidates (rows) x Time (cols)
                
                # Get universe of unique timestamps across this family
                all_events = set()
                cand_to_idx = {c.uuid: i for i, c in enumerate(family_cands)}
                
                for c in family_cands:
                    all_events.update(getattr(c, 'events', []))
                
                if not all_events:
                    filtered_candidates.extend(family_cands)
                    continue
                    
                sorted_timeline = sorted(list(all_events))
                time_map = {t: i for i, t in enumerate(sorted_timeline)}
                
                n_cands = len(family_cands)
                n_times = len(sorted_timeline)
                
                # Use scipy sparse matrix for efficiency
                from scipy.sparse import csr_matrix
                
                rows = []
                cols = []
                data = []
                
                for i, cand in enumerate(family_cands):
                    evts = getattr(cand, 'events', [])
                    for t in evts:
                        if t in time_map:
                            rows.append(i)
                            cols.append(time_map[t])
                            data.append(1)
                            
                # Binary event matrix E (Candidates x Time)
                E = csr_matrix((data, (rows, cols)), shape=(n_cands, n_times), dtype=np.float32)
                
                # Compute Intersection: E @ E.T
                # Result[i, j] = number of common events between cand i and cand j
                intersection_mat = E @ E.T
                
                # Compute Union: |A| + |B| - |A ∩ B|
                # Row sums give |A| (number of events per candidate)
                n_events_per_cand = np.array(E.sum(axis=1)).flatten()
                
                # Use broadcasting to get Sum matrix: sum_mat[i, j] = |A| + |B|
                # n_events_per_cand is (N,), we want (N, N)
                sum_mat = n_events_per_cand[:, None] + n_events_per_cand[None, :]
                
                # Union = Sum - Intersection
                # Note: valid indices only where union > 0
                
                # Iterate through sorted candidates (by score) and greedily prune
                # Sort indices by score descending
                sorted_idx = sorted(
                    range(n_cands), 
                    key=lambda k: getattr(family_cands[k], 'final_score', 0), 
                    reverse=True
                )
                
                keep_mask = np.ones(n_cands, dtype=bool)
                
                # Dense conversion of intersection for fast access (it's N_cands x N_cands, reasonably small)
                # But maximize memory safety: if N > 5000, keep sparse
                if n_cands < 5000:
                    I_dense = intersection_mat.toarray()
                else:
                    I_dense = None # Fallback to sparse access
                
                for i in range(n_cands):
                    idx_i = sorted_idx[i]
                    if not keep_mask[idx_i]:
                        continue
                        
                    # Compare with lower-ranked candidates
                    for j in range(i + 1, n_cands):
                        idx_j = sorted_idx[j]
                        if not keep_mask[idx_j]:
                            continue
                            
                        # Get Intersection
                        if I_dense is not None:
                            inter = I_dense[idx_i, idx_j]
                        else:
                            inter = intersection_mat[idx_i, idx_j]
                            
                        # Get Union
                        union_val = n_events_per_cand[idx_i] + n_events_per_cand[idx_j] - inter
                        
                        if union_val > 0:
                            sim = inter / union_val
                            if sim > max_correlation:
                                # Prune lower ranked candidate
                                keep_mask[idx_j] = False
                                total_pruned += 1
                                
                # Reconstruct list
                for i in range(n_cands):
                    if keep_mask[i]:
                        filtered_candidates.append(family_cands[i])
                        
            except Exception as e:
                tprint_warning(f"   ⚠️ Vectorized pre-filter failed for {family}: {e}. Falling back to loop.")
                # Fallback to loop logic (re-implemented briefly or just pass through)
                filtered_candidates.extend(family_cands) # Fail safe: don't prune
        
        if total_pruned > 0:
            tprint_info(f"   🔧 Pre-filter (Vectorized): Pruned {total_pruned} redundant candidates (ρ>{max_correlation:.2f})")
        else:
            tprint_info(f"   🔧 Pre-filter: No redundant candidates found (ρ>{max_correlation:.2f}) out of {len(candidates)} candidates.")
            
        tprint_info(f"   ✅ Prefilter correlated candidates done kept={len(filtered_candidates)}")
        return filtered_candidates

    def _enforce_cross_family_diversity(
        self, 
        geometries: List['GeometryTrial'],
        max_similarity: float = 0.90,  # Jaccard threshold only
    ) -> List['GeometryTrial']:
        """
        Enforce diversity across geometries from different families.
        
        Removes geometries with event overlap (Jaccard) > 90%.
        Uses only Jaccard similarity - metrics can legitimately be similar.
        
        Args:
            geometries: List of selected geometries from all families
            max_similarity: Maximum allowed Jaccard similarity (default 0.90)
            
        Returns:
            Filtered list of diverse geometries
        """
        tprint_info(f"   🔀 Cross-family diversity start count={len(geometries)}")
        if len(geometries) < 2:
            tprint_info("   ✅ Cross-family diversity skip (insufficient geometries)")
            return geometries
        
        # Sort by ranking score (higher is better)
        sorted_geos = sorted(
            geometries,
            key=lambda x: getattr(x, 'ranking_score', getattr(x, 'probe_score', 0)),
            reverse=True
        )
        
        # Vectorized Cross-Family Diversity
        try:
            # 1. Index Universe
            all_events = set()
            for g in sorted_geos:
                all_events.update(getattr(g, 'events', []))
                
            if not all_events:
                tprint_info("   ✅ Cross-family diversity skip (no events)")
                return sorted_geos
                
            sorted_timeline = sorted(list(all_events))
            time_map = {t: i for i, t in enumerate(sorted_timeline)}
            
            n_geos = len(sorted_geos)
            n_times = len(sorted_timeline)
            
            # 2. Sparse Matrix Construction
            from scipy.sparse import csr_matrix
            rows, cols, data = [], [], []
            
            for i, geo in enumerate(sorted_geos):
                evts = getattr(geo, 'events', [])
                for t in evts:
                    if t in time_map:
                        rows.append(i)
                        cols.append(time_map[t])
                        data.append(1)
            
            E = csr_matrix((data, (rows, cols)), shape=(n_geos, n_times), dtype=np.float32)
            
            # 3. Intersection & Union
            # Intersection = E @ E.T
            I_mat = E @ E.T
            
            # Count per geo
            counts = np.array(E.sum(axis=1)).flatten()
            
            # 4. Pruning Loop using computed matrix
            keep_mask = np.ones(n_geos, dtype=bool)
            redundant_pairs = []
            
            # Use dense access for small/med matrices
            if n_geos < 5000:
                I_dense = I_mat.toarray()
            else:
                I_dense = None 
                
            for i in range(n_geos):
                if not keep_mask[i]: continue
                
                geo_i = sorted_geos[i]
                
                for j in range(i + 1, n_geos):
                    if not keep_mask[j]: continue
                    
                    geo_j = sorted_geos[j]
                    
                    # Get Intersection
                    if I_dense is not None:
                        inter = I_dense[i, j]
                    else:
                        inter = I_mat[i, j]
                    
                    union = counts[i] + counts[j] - inter
                    jaccard = inter / union if union > 0 else 0
                    
                    if jaccard > max_similarity:
                        keep_mask[j] = False
                        redundant_pairs.append((geo_i.uuid[:20], geo_j.uuid[:20], f"J={jaccard:.2f}"))
            
            diverse_geos = [sorted_geos[k] for k in range(n_geos) if keep_mask[k]]
                    
        except Exception as e:
            tprint_warning(f"   ⚠️ Vectorized diversity check failed: {e}. Return all.")
            tprint_warning("   ⚠️ Cross-family diversity fallback to original set")
            return geometries # Fail safe
            
        if redundant_pairs:
            tprint_info(f"   🧹 Cross-family diversity (Vectorized): Removed {len(redundant_pairs)} redundant geometry pairs")
            for pair in redundant_pairs[:3]:  # Log first 3
                tprint_info(f"      - {pair[0]} ≈ {pair[1]} ({pair[2]})")
        
        tprint_info(f"   ✅ Cross-family diversity done kept={len(diverse_geos)}")
        return diverse_geos

    # -------------------------------------------------------------------------
    # STRUCTURAL FAMILY CLASSIFICATION & QUOTA ENFORCEMENT
    # -------------------------------------------------------------------------
    
    # Define structural families for diversity enforcement
    STRUCTURAL_FAMILIES = {
        'VOLATILITY': ['volatility', 'vol_ratio', 'vol_spike', 'realized_vol', 'rv_z'],
        'FLOW': ['flow', 'imbalance', 'pressure', 'buy_vol', 'sell_vol', 'vwap'],
        'RELAXATION': ['relaxation', 'decay', 'reversion', 'distance', 'mean_revert'],
        'SLOPE': ['slope', 'curvature', 'trend', 'momentum', 'linear_reg'],
        'FRAGILITY': ['fragility', 'resilience', 'kyle', 'illiquidity', 'impact'],
    }
    
    FAMILY_QUOTAS = {
        'VOLATILITY': 1,
        'FLOW': 1,
        'RELAXATION': 0,  # Optional - nice to have
        'SLOPE': 0,       # Optional
        'FRAGILITY': 0,   # Optional
    }

    def _detect_geometry_family(self, geometry: 'GeometryTrial') -> str:
        """
        Classify a geometry into one of the structural families.
        
        Args:
            geometry: Geometry to classify
            
        Returns:
            Family name (VOLATILITY, FLOW, RELAXATION, SLOPE, FRAGILITY, or OTHER)
        """
        uuid_lower = getattr(geometry, 'uuid', '').lower()
        family_lower = getattr(geometry, 'family', '').lower()
        search_text = f"{uuid_lower} {family_lower}"
        
        for struct_family, keywords in self.STRUCTURAL_FAMILIES.items():
            if any(kw in search_text for kw in keywords):
                return struct_family
        
        return 'OTHER'
    
    def _enforce_family_representation(
        self,
        geometries: List['GeometryTrial'],
        family_quotas: Optional[Dict[str, int]] = None
    ) -> List['GeometryTrial']:
        """
        Ensure minimum representation from each structural family.
        
        De Prado principle: Diverse base models prevent correlated failures.
        This reorders/prioritizes geometries to meet family quotas.
        
        Args:
            geometries: List of geometry candidates
            family_quotas: Minimum required geometries per family
            
        Returns:
            Reordered list with family representation ensured
        """
        tprint_info(f"   🧬 Enforce family representation start count={len(geometries)}")
        if not geometries:
            tprint_info("   ✅ Enforce family representation skip (no geometries)")
            return geometries
        
        quotas = family_quotas or self.FAMILY_QUOTAS
        
        # Classify all geometries
        family_buckets: Dict[str, List['GeometryTrial']] = {k: [] for k in quotas.keys()}
        family_buckets['OTHER'] = []
        
        for geo in geometries:
            struct_family = self._detect_geometry_family(geo)
            if struct_family in family_buckets:
                family_buckets[struct_family].append(geo)
            else:
                family_buckets['OTHER'].append(geo)
        
        # Log family distribution
        tprint_info("   🔀 Structural family distribution:")
        for fam, geos in family_buckets.items():
            if geos or quotas.get(fam, 0) > 0:
                quota = quotas.get(fam, 0)
                status = "✅" if len(geos) >= quota else "⚠️"
                tprint_info(f"      {status} {fam}: {len(geos)} geometries (min={quota})")
        
        # Build result: prioritize meeting quotas, then add others
        result = []
        
        # First pass: take quota from each family
        for fam, quota in quotas.items():
            available = family_buckets.get(fam, [])
            # Sort by score and take up to quota
            available_sorted = sorted(
                available,
                key=lambda x: getattr(x, 'ranking_score', getattr(x, 'probe_score', 0)),
                reverse=True
            )
            taken = available_sorted[:quota]
            result.extend(taken)
            
            # Mark as used
            for geo in taken:
                if geo in available:
                    available.remove(geo)
        
        # Second pass: add remaining geometries (sorted by score)
        remaining = []
        for fam, geos in family_buckets.items():
            remaining.extend(geos)
        
        # Prioritize Tier-2 geometries
        tier2_geos = [g for g in remaining if getattr(g, 'is_tier2', False)]
        remaining = [g for g in remaining if not getattr(g, 'is_tier2', False)]
        
        remaining_sorted = sorted(
            remaining,
            key=lambda x: getattr(x, 'ranking_score', getattr(x, 'probe_score', 0)),
            reverse=True
        )
        result.extend(tier2_geos + remaining_sorted)
        
        # Deduplicate while preserving order
        seen = set()
        final_result = []
        for geo in result:
            geo_id = id(geo)
            if geo_id not in seen:
                seen.add(geo_id)
                final_result.append(geo)
        
        return final_result

    def _validate_framework_separation(self) -> None:
        """
        Validate that AFML and Causal frameworks are properly separated.
        """
        if self.enable_causal_framework:
            tprint_info("🔍 Validating Framework Separation...")

        if self.enable_causal_framework:
            tprint_info("🔬 Using Causal Framework (De Prado 2026)")
            # Verify critical dependencies
            if not CAUSAL_MODULES_AVAILABLE:
                tprint_error("❌ Causal framework enabled but modules not found!")
                raise ImportError("Causal modules missing")
        else:
            tprint_warning("⚠️ Legacy AFML framework detected but deprecated. Forcing Causal Framework.")
            self.enable_causal_framework = True
            tprint_info("💡 Enabling causal framework automatically.")

